// common.h - shared infrastructure for the bedtools reimplementation
#ifndef BT_COMMON_H
#define BT_COMMON_H

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cctype>
#include <cerrno>
#include <string>
#include <vector>
#include <map>
#include <set>
#include <unordered_map>
#include <algorithm>
#include <iostream>
#include <fstream>
#include <sstream>
#include <iomanip>
#include <zlib.h>
#include <unistd.h>

using std::string;
using std::vector;
using std::map;
using std::pair;

extern const char *BT_VERSION;

// ---------------- error handling ----------------
// prints "Error: <msg>" on stderr and exits 1
[[noreturn]] void die(const string &msg);
// prints "***** ERROR: <msg> *****" on stderr and exits 1
[[noreturn]] void bedFatal(const string &msg);
// prints the error after flushing whatever is in the output buffer
[[noreturn]] void dieFlush(const string &msg);

// ---------------- output buffer ----------------
class OutBuf {
public:
    string buf;
    bool nobuf;
    OutBuf() : nobuf(false) {}
    void add(const string &s) {
        if (nobuf) { fwrite(s.data(), 1, s.size(), stdout); }
        else buf.append(s);
    }
    void flush() {
        if (buf.size()) { fwrite(buf.data(), 1, buf.size(), stdout); buf.clear(); }
    }
};
extern OutBuf OUT;

static inline void outLine(const string &s) { OUT.add(s); OUT.add("\n"); }

// ---------------- record ----------------
struct BedRec {
    vector<string> fields;   // raw fields (all columns)
    long start, end;
    string chrom() const { return fields[0]; }
    long len() const { return end - start; }
    string strand() const { return fields.size() >= 6 ? fields[5] : string(); }
    bool hasStrand() const { return fields.size() >= 6; }
    string raw() const;
};

string joinFields(const vector<string> &f);

// ---------------- file reading ----------------
enum FileType { FT_BED, FT_VCF, FT_BAM };

class LineReader {
public:
    LineReader(const string &path);
    ~LineReader();
    bool ok() const { return _ok; }
    // returns false on EOF; empty lines are returned as ""
    bool next(string &line);
    bool isGz() const { return _gz; }
    bool isBzip() const { return _bzip; }
private:
    FILE *_fp;
    gzFile _gzf;
    bool _gz, _bzip, _ok;
    string _pend;
    bool _init;
    void fill();
};

// A reader for BED/GFF/VCF (text) interval files.
class BedReader {
public:
    string path;
    FileType type;
    vector<string> header;
    // raw pending records: tokenized, field count already verified
    vector<vector<string> > recs;
    size_t pos;
    bool valid;

    BedReader();
    void open(const string &p);
    // true if another record is available; parse/validate errors reported here
    bool next(BedRec &r);
    size_t size() const { return recs.size(); }
    void close();
private:
    void detectType();
};

// load all records of a file into a vector<BedRec>
void loadRecords(const string &path, vector<BedRec> &out, vector<string> &header);

// ---------------- genome files ----------------
class GenomeFile {
public:
    bool ok;
    vector<string> chroms;
    map<string, long> lens;
    GenomeFile() : ok(false) {}
    void load(const string &path);
    bool has(const string &c) const { return lens.count(c) > 0; }
    long size(const string &c) const { map<string,long>::const_iterator it = lens.find(c); return it == lens.end() ? -1 : it->second; }
    int index(const string &c) const;
};

// ---------------- misc helpers ----------------
bool parseInt(const string &s, long &v);
bool isInteger(const string &s);
double parseDouble(const string &s, bool &ok);
string num2str(long v);
string dbl2str(double v, int prec);
void splitStr(const string &s, char delim, vector<string> &out);
string toLower(const string &s);
bool isHeaderLine(const string &line);
bool fileExists(const string &path);
bool isDir(const string &path);

#endif
EOF
echo ok"}

