    for (size_t i = 0; i < r.size(); ++i) r[i] = (char)tolower((unsigned char)r[i]);
    return r;
}

bool isHeaderLine(const string &line) {
    if (line.size() && line[0] == '#') return true;
    if (line.size() >= 5 && line.compare(0, 5, "track") == 0) return true;
    if (line.size() >= 7 && line.compare(0, 7, "browser") == 0) return true;
    return false;
}

bool fileExists(const string &path) {
    FILE *f = fopen(path.c_str(), "r");
    if (f) { fclose(f); return true; }
    return false;
}

bool isDir(const string &path) {
    struct stat st;
    if (stat(path.c_str(), &st) != 0) return false;
    return S_ISDIR(st.st_mode);
}

bool parseInt(const string &s, long &v) {
    if (s.empty()) return false;
    const char *p = s.c_str();
    char *end = NULL;
    errno = 0;
    long long r = strtoll(p, &end, 10);
    if (end == p || *end != '\0') return false;
    if (errno == ERANGE) return false;
    v = (long)r;
    return true;
}

bool isInteger(const string &s) {
    long v;
    return parseInt(s, v);
}

double parseDouble(const string &s, bool &ok) {
    ok = false;
    const char *p = s.c_str();
    char *end = NULL;
    errno = 0;
    double d = strtod(p, &end);
    if (end == p || *end != '\0') return 0;
    ok = true;
    return d;
}

string num2str(long v) {
    char buf[32];
    snprintf(buf, sizeof(buf), "%ld", v);
    return string(buf);
}

string dbl2str(double v, int prec) {
    std::ostringstream ss;
    ss << std::setprecision(prec) << std::fixed << v;
    return ss.str();
}

// ---------------- LineReader ----------------
// emulate the C++ failure bedtools exhibits for directories
[[noreturn]] static void dirFailure() {
    fprintf(stderr, "terminate called after throwing an instance of 'std::__ios_failure'\n");
    fprintf(stderr, "  what():  basic_filebuf::underflow error reading the file: Is a directory\n");
    fflush(stderr);
    abort();
}

LineReader::LineReader(const string &path) {
    _fp = NULL; _gzf = NULL; _gz = false; _bzip = false; _ok = false; _init = false;
    if (isDir(path)) dirFailure();
    if (path == "-") {
        _gzf = gzdopen(fileno(stdin), "rb");
    } else {
        if (path.size() > 3 && path.compare(path.size()-3, 3, ".gz") == 0) _gz = true;
        _gzf = gzopen(path.c_str(), "rb");
    }
    if (!_gzf) {
        die("Unable to open file " + path + ". Exiting.");
    }
    // peek at the first bytes to detect binary formats
    unsigned char hdr[4];
    int n = gzread(_gzf, hdr, 4);
    if (n == 4 && memcmp(hdr, "BAM\x01", 4) == 0) {
        // BAM file; rewind, caller handles
        gzrewind(_gzf);
        _ok = true;
        return;
    }
    if (n >= 3 && memcmp(hdr, "BZh", 3) == 0) {
        gzclose(_gzf);
        dieFlush("Unable to determine type for file " + path);
    }
    gzrewind(_gzf);
    _ok = true;
}

LineReader::~LineReader() { if (_gzf) gzclose(_gzf); }

void LineReader::fill() {
    char tmp[65536];
    int n = gzread(_gzf, tmp, sizeof(tmp));
    if (n > 0) _pend.append(tmp, n);
}

bool LineReader::next(string &line) {
    while (true) {
        size_t p = _pend.find('\n');
        if (p != string::npos) {
            line = _pend.substr(0, p);
            _pend.erase(0, p + 1);
            if (line.size() && line[line.size()-1] == '\r') line.erase(line.size()-1);
            return true;
        }
        size_t before = _pend.size();
        fill();
        if ((int)before == (int)_pend.size()) {
            int err;
            gzerror(_gzf, &err);
            if (_pend.size()) { line = _pend; _pend.clear(); return true; }
            return false;
        }
    }
}

// ---------------- BedReader ----------------
BedReader::BedReader() : type(FT_BED), pos(0), valid(false) {}

void BedReader::close() { recs.clear(); pos = 0; valid = false; }

void BedReader::open(const string &p) {
    path = p;
    type = FT_BED;
    header.clear();
    recs.clear();
    pos = 0;
    valid = true;

    LineReader lr(p);
    if (!lr.ok()) die("Unable to open file " + p + ". Exiting.");

    // Peek to see if this is a BAM file
    {
        unsigned char hdr[4];
        FILE *tf = fopen(p.c_str(), "rb");
        bool bam = false;
        if (tf) {
            int n = (int)fread(hdr, 1, 4, tf);
            fclose(tf);
            if (n == 4 && memcmp(hdr, "BAM\x01", 4) == 0) bam = true;
        }
        if (bam) { type = FT_BAM; return; }
    }

    bool isVcf = false;
    string line;
    bool haveFirst = false;
    size_t expect = 0;
    vector<string> f;

    while (lr.next(line)) {
        if (line.empty()) continue;
        if (line.compare(0, 16, "##fileformat=VCF") == 0) { isVcf = true; }
        if (line[0] == '#' ) { header.push_back(line); continue; }
        if (line.size() >= 5 && line.compare(0,5,"track") == 0) { header.push_back(line); continue; }
        if (line.size() >= 7 && line.compare(0,7,"browser") == 0) { header.push_back(line); continue; }

        splitStr(line, '\t', f);
        if (!haveFirst) {
            haveFirst = true;
            expect = f.size();
            // detection
            bool bad = false;
            if (f.size() < 3) bad = true;
            long s = 0, e = 0;
            if (!bad && !parseInt(f[1], s)) bad = true;
            if (!bad && !parseInt(f[2], e)) bad = true;
            if (!bad && s > e) bad = true;
            if (bad) {
                die("unable to open file or unable to determine types for file " + p +
                    "\n\n- Please ensure that your file is TAB delimited (e.g., cat -t FILE).\n"
                    "- Also ensure that your file has integer chromosome coordinates in the \n"
                    "  expected columns (e.g., cols 2 and 3 for BED).");
            }
            type = isVcf ? FT_VCF : FT_BED;
            if (type == FT_VCF && f.size() < 5) {
                fprintf(stderr, "terminate called after throwing an instance of 'std::length_error'\n");
                fprintf(stderr, "  what():  basic_string::_M_replace\n");
                fflush(stderr);
                abort();
            }
            recs.push_back(f);
            continue;
        }
        if (f.size() != expect) {
            die("Type checker found wrong number of fields while tokenizing data line.\n"
                "Perhaps you have extra TAB at the end of your line? Check with \"cat -t\"");
        }
        recs.push_back(f);
    }
    if (isVcf && !haveFirst) {
        die("unable to open file or unable to determine types for file " + p +
            "\n\n- Please ensure that your file is TAB delimited (e.g., cat -t FILE).\n"
            "- Also ensure that your file has integer chromosome coordinates in the \n"
            "  expected columns (e.g., cols 2 and 3 for BED).");
    }
    pos = 0;
}

bool BedReader::next(BedRec &r) {
    if (pos >= recs.size()) return false;
    const vector<string> &f = recs[pos++];
    long s = 0, e = 0;
    if (!parseInt(f[1], s)) {
        bedFatal("illegal number \"" + f[1] + "\". Exiting...");
    }
    if (!parseInt(f[2], e)) {
        bedFatal("illegal number \"" + f[2] + "\". Exiting...");
    }
    if (type == FT_VCF) { s = s - 1; e = s + 1; }
    r.fields = f;
    r.start = s; r.end = e;
    if (s < 0 || s > e) {
        dieFlush("Invalid record in file " + path + ". Record is \n" + joinFields(f));
    }
    return true;
}

void loadRecords(const string &path, vector<BedRec> &out, vector<string> &header) {
    out.clear(); header.clear();
    BedReader br;
    br.open(path);
    header = br.header;
    BedRec r;
    while (br.next(r)) out.push_back(r);
}

// ---------------- GenomeFile ----------------
void GenomeFile::load(const string &path) {
    ok = true;
    chroms.clear(); lens.clear();
    LineReader lr(path);
    if (!lr.ok()) die("Unable to open file " + path + ". Exiting.");
    string line;
    while (lr.next(line)) {
        if (line.empty()) continue;
        if (line[0] == '#') continue;
        vector<string> f;
        splitStr(line, '\t', f);
        if (f.size() < 2) {
            die("Error: unable to parse genome file " + path + ".");
        }
        long v = 0;
        if (!parseInt(f[1], v)) {
            die("Error: unable to parse genome file " + path + ".");
        }
        chroms.push_back(f[0]);
        lens[f[0]] = v;
    }
}

int GenomeFile::index(const string &c) const {
    for (size_t i = 0; i < chroms.size(); ++i) if (chroms[i] == c) return (int)i;
    return -1;
}
