#include "numops.h"
#include <cmath>
#include <cstdio>

static string fmt(double v, int prec) {
    std::ostringstream ss;
    ss << std::setprecision(prec) << v;
    return ss.str();
}

static void warnNonNumeric(const string &v, int colNum) {
    fprintf(stderr, " ***** WARNING: Non numeric value %s in %d.\n", v.c_str(), colNum);
}

static bool doubles(const vector<string> &vals, int colNum, vector<double> &out,
                    bool warnEvery) {
    bool allNum = true;
    for (size_t i = 0; i < vals.size(); ++i) {
        bool ok = false;
        double d = parseDouble(vals[i], ok);
        if (!ok) {
            warnNonNumeric(vals[i], colNum);
            allNum = false;
            continue;
        }
        out.push_back(d);
    }
    return allNum;
}

string applyNumOp(const string &op, const vector<string> &vals,
                  const string &delim, int prec, int colNum) {
    // string based ops
    if (op == "count") return num2str((long)vals.size());
    if (op == "first") return vals.empty() ? "." : vals[0];
    if (op == "last") return vals.empty() ? "." : vals.back();
    if (op == "concat") {
        string s;
        for (size_t i = 0; i < vals.size(); ++i) s += vals[i];
        return s;
    }
    if (op == "collapse") {
        string s;
        for (size_t i = 0; i < vals.size(); ++i) {
            if (i) s += delim;
            s += vals[i];
        }
        return s;
    }
    if (op == "distinct" || op == "distinct_only" || op == "count_distinct" ||
        op == "distinct_sort_num" || op == "distinct_sort_num_desc") {
        // appearance-ordered unique list
        vector<string> uniq;
        map<string,int> cnt;
        for (size_t i = 0; i < vals.size(); ++i) {
            if (cnt.find(vals[i]) == cnt.end()) {
                cnt[vals[i]] = 1;
                uniq.push_back(vals[i]);
            } else cnt[vals[i]]++;
        }
        if (op == "count_distinct") return num2str((long)uniq.size());
        if (op == "distinct") {
            string s;
            for (size_t i = 0; i < uniq.size(); ++i) { if (i) s += delim; s += uniq[i]; }
            return s;
        }
        if (op == "distinct_only") {
            string s;
            for (map<string,int>::iterator it = cnt.begin(); it != cnt.end(); ++it) {
                if (it->second == 1) {
                    s += it->first;
                    s += delim;
                } else if (s.empty()) {
                    s += delim;
                }
            }
            if (s.size() && s[s.size()-1] == delim[0]) s.erase(s.size()-1);
            return s;
        }
        // numeric sorts: convert values
        vector<pair<double,string> > pv;
        for (size_t i = 0; i < uniq.size(); ++i) {
            bool ok = false;
            double d = parseDouble(uniq[i], ok);
            if (!ok) { warnNonNumeric(uniq[i], colNum); pv.push_back(make_pair(0.0, string("nan"))); }
            else pv.push_back(make_pair(d, uniq[i]));
        }
        std::stable_sort(pv.begin(), pv.end(), [](const pair<double,string>&a, const pair<double,string>&b){ return a.first < b.first; });
        string s;
        if (op == "distinct_sort_num") {
            for (size_t i = 0; i < pv.size(); ++i) { if (i) s += delim; s += pv[i].second; }
        } else {
            for (int i = (int)pv.size()-1; i >= 0; --i) { if (i != (int)pv.size()-1) s += delim; s += pv[i].second; }
        }
        return s;
    }
    if (op == "mode" || op == "antimode") {
        map<string,int> cnt;
        for (size_t i = 0; i < vals.size(); ++i) cnt[vals[i]]++;
        string best; int bestc = -1;
        for (map<string,int>::iterator it = cnt.begin(); it != cnt.end(); ++it) {
            if (op == "mode") {
                if (bestc < 0 || it->second > bestc) { bestc = it->second; best = it->first; }
            } else {
                if (bestc < 0 || it->second < bestc) { bestc = it->second; best = it->first; }
            }
        }
        return best;
    }

    // numeric ops
    vector<double> d;
    bool allNum = doubles(vals, colNum, d, true);
    if (op == "sum" || op == "mean" || op == "median" || op == "stdev" || op == "sstdev") {
        if (!allNum || d.empty()) return ".";
        double sum = 0;
        for (size_t i = 0; i < d.size(); ++i) sum += d[i];
        if (op == "sum") return fmt(sum, prec);
        if (op == "mean") return fmt(sum / (double)d.size(), prec);
        if (op == "median") {
            vector<double> v = d;
            std::sort(v.begin(), v.end());
            size_t n = v.size();
            if (n % 2 == 1) return fmt(v[n/2], prec);
            return fmt((v[n/2-1] + v[n/2]) / 2.0, prec);
        }
        // stdev / sstdev
        double mean = sum / (double)d.size();
        double ss = 0;
        for (size_t i = 0; i < d.size(); ++i) ss += (d[i]-mean)*(d[i]-mean);
        if (op == "stdev") return fmt(sqrt(ss / (double)d.size()), prec);
        if (d.size() < 2) return ".";
        return fmt(sqrt(ss / (double)(d.size()-1)), prec);
    }
    if (op == "min" || op == "max" || op == "absmin" || op == "absmax") {
        if (d.empty()) return ".";
        double best = d[0];
        for (size_t i = 1; i < d.size(); ++i) {
            double v = d[i];
            if (op == "min" && v < best) best = v;
            else if (op == "max" && v > best) best = v;
            else if (op == "absmin" && fabs(v) < fabs(best)) best = v;
            else if (op == "absmax" && fabs(v) > fabs(best)) best = v;
        }
        return fmt(best, prec);
    }
    return ".";
}

bool isValidOp(const string &op) {
    static const char *ops[] = {"sum","min","max","absmin","absmax","mean","median","mode",
        "antimode","stdev","sstdev","collapse","distinct","distinct_sort_num",
        "distinct_sort_num_desc","distinct_only","count","count_distinct","first","last","concat",NULL};
    for (int i = 0; ops[i]; ++i) if (op == ops[i]) return true;
    return false;
}
