// core.cpp - bin index, overlap logic and reporting shared by many tools
#include "tools.h"
#include "numops.h"
#include <cmath>

GenomeFile GENOME;

// bedtools bin scheme: level 5..1 sizes, level 0 = root (whole chromosome)
const long BIN_SIZES[5] = {16384, 131072, 1048576, 8388608, 67108864};
const long BIN_BASES[5] = {5849, 585, 73, 9, 1};

static inline long idiv(long a, long b) {
    // C++ truncation toward zero
    if (b == 0) return 0;
    long q = a / b;
    if ((a % b != 0) && ((a < 0) != (b < 0))) q--;
    return q;
}

void ChromIndex::build(vector<BedRec> &recsIn) {
    clear();
    recs.swap(recsIn);
    for (size_t i = 0; i < recs.size(); ++i) {
        long s = recs[i].start, e = recs[i].end;
        int level = 5;
        long bin = 0;
        for (int k = 0; k < 5; ++k) {
            if (idiv(s, BIN_SIZES[k]) == idiv(e - 1, BIN_SIZES[k])) {
                level = k;
                bin = BIN_BASES[k] + idiv(s, BIN_SIZES[k]);
                break;
            }
        }
        if (level == 5) { bins[5][0].push_back((int)i); }  // root
        else bins[level][bin].push_back((int)i);
    }
}

void ChromIndex::query(long qs, long qe, vector<int> &out) const {
    out.clear();
    if (qe <= qs) return;
    long qe1 = qe - 1;
    for (int k = 0; k < 5; ++k) {
        long b1 = BIN_BASES[k] + idiv(qs, BIN_SIZES[k]);
        long b2 = BIN_BASES[k] + idiv(qe1, BIN_SIZES[k]);
        if (b2 < b1) continue;
        std::map<long, vector<int> >::const_iterator lo = bins[k].lower_bound(b1);
        std::map<long, vector<int> >::const_iterator hi = bins[k].upper_bound(b2);
        for (; lo != hi; ++lo) {
            const vector<int> &v = lo->second;
            for (size_t j = 0; j < v.size(); ++j) out.push_back(v[j]);
        }
