void FileBins::build(vector<BedRec> &recs) {
    byChrom.clear();
    map<string, vector<BedRec> > groups;
    for (size_t i = 0; i < recs.size(); ++i) groups[recs[i].chrom()].push_back(recs[i]);
    for (map<string, vector<BedRec> >::iterator it = groups.begin(); it != groups.end(); ++it) {
        ChromBins &cb = byChrom[it->first];
        cb.build(it->second);
    }
}

const ChromBins *FileBins::get(const string &chrom) const {
    map<string, ChromBins>::const_iterator it = byChrom.find(chrom);
    if (it == byChrom.end()) return NULL;
    return &it->second;
}
