// the "null" record used by -loj/-wao; field 5 becomes -1 when the template
// record has a numeric score column (matches bedtools behaviour)
BedRec nullRecFor(const BedRec &tpl) {
    BedRec r;
    r.fields.push_back(".");
    r.fields.push_back("-1");
    r.fields.push_back("-1");
    bool scoreNum = (tpl.fields.size() > 4) && isInteger(tpl.fields[4]);
    for (size_t i = 3; i < tpl.fields.size(); ++i) {
        r.fields.push_back((i == 4 && scoreNum) ? string("-1") : string("."));
    }
    r.start = -1; r.end = -1;
    return r;
}
