        if (bad) {
            if (useGenome)
                die("Sorted input specified, but the file " + path +
                    " has the following record with a different sort order than the genomeFile " +
                    o.genomePath + "\\n" + recs[i].raw());
            else
                die("Sorted input specified, but the file " + path +
