{"command": "cat > /workspace/src/tools_inter2.cpp <<'EOF'
// tools_inter2.cpp - window, coverage, map, closest, subtract, overlap
#include "tools.h"
#include "numops.h"
#include <cmath>

struct Hit {
    int file;
    int idx;
    const BedRec *rec;
};
static vector<int> tmp;

static void loadFiles(const vector<string> &paths, vector<FileBins> &out,
                      vector<vector<BedRec> > &recsets) {
    out.clear(); recsets.clear();
    for (size_t i = 0; i < paths.size(); ++i) {
        vector<BedRec> recs;
        vector<string> hdr;
        loadRecords(paths[i], recs, hdr);
        FileBins fb; fb.build(recs);
        out.push_back(fb);
        recsets.push_back(recs);
    }
}

static void collect(const vector<FileBins> &bsets, const string &chrom, long qs, long qe,
                    vector<Hit> &hits) {
    hits.clear();
    for (size_t f = 0; f < bsets.size(); ++f) {
        const ChromBins *cb = bsets[f].get(chrom);
        if (!cb) continue;
        cb->query(qs, qe, tmp);
        for (size_t j = 0; j < tmp.size(); ++j) {
            Hit h; h.file = (int)f; h.idx = tmp[j]; h.rec = &cb->recs[tmp[j]];
            hits.push_back(h);
        }
    }
}

// ---------- window ----------
int cmd_window(int argc, char **argv) {
    BinOpts o;
    string aFile;
    vector<string> bFiles;
    long w = 1000, wl = -1, wr = -1;
    bool u = false, c = false, v = false, sw = false;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("window"); }
        else if (arg == "-abam" || arg == "-ubam" || arg == "-bed") { }
        else if (arg == "-w") { if (i+1 >= argc) bedFatal("Please specify a value for -w"); w = atol(argv[++i]); }
        else if (arg == "-l") { if (i+1 >= argc) bedFatal("Please specify a value for -l"); wl = atol(argv[++i]); }
        else if (arg == "-r") { if (i+1 >= argc) bedFatal("Please specify a value for -r"); wr = atol(argv[++i]); }
        else if (arg == "-sw") sw = true;
        else if (arg == "-sm") { o.sameStrand = true; }
        else if (arg == "-Sm") { o.diffStrand = true; }
        else if (arg == "-u") u = true;
        else if (arg == "-c") c = true;
        else if (arg == "-v") v = true;
        else if (arg == "-a") { if (i+1 >= argc) bedFatal("No input file given. Exiting."); aFile = argv[++i]; }
        else if (arg == "-b") {
            if (i+1 >= argc) bedFatal("-b option given, but no database file specified.");
            ++i;
            while (i < argc && argv[i][0] != '-') bFiles.push_back(argv[i++]);
            --i;
        }
        else if (parseCommonOpt(arg, argc, argv, i, o)) {}
        else { fputs(HELP_window, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (aFile.empty()) { fputs(HELP_window, stderr); bedFatal("No input file given. Exiting."); }
    if (bFiles.empty()) { fputs(HELP_window, stderr); bedFatal("query and database files not specified."); }
    long l = wl >= 0 ? wl : w;
    long r = wr >= 0 ? wr : w;
    vector<FileBins> bsets;
    vector<vector<BedRec> > recsets;
