// ---------- coverage ----------
int cmd_coverage(int argc, char **argv) {
    BinOpts o;
    string aFile;
    vector<string> bFiles;
    bool d = false, hist = false, counts = false, mean = false;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("coverage"); }
        else if (arg == "-d") d = true;
        else if (arg == "-hist") hist = true;
        else if (arg == "-counts") counts = true;
        else if (arg == "-mean") mean = true;
        else if (arg == "-a") { if (i+1 >= argc) bedFatal("No input file given. Exiting."); aFile = argv[++i]; }
        else if (arg == "-b") {
            if (i+1 >= argc) bedFatal("-b option given, but no database file specified.");
            ++i;
            while (i < argc && argv[i][0] != '-') bFiles.push_back(argv[i++]);
            --i;
        }
        else if (parseCommonOpt(arg, argc, argv, i, o)) {}
        else { fputs(HELP_coverage, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (aFile.empty()) { fputs(HELP_coverage, stderr); bedFatal("No input file given. Exiting."); }
    if (bFiles.empty()) { fputs(HELP_coverage, stderr); bedFatal("query and database files not specified."); }
    if (o.anyWhere && !o.fracASet) { fputs(HELP_coverage, stderr); bedFatal("-e must be used with -f."); }
    if (o.anyWhere && !o.fracBSet) o.fracB = 0.0;

    vector<FileBins> bsets;
    vector<vector<BedRec> > recsets;
    loadFiles(bFiles, bsets, recsets);
    vector<BedRec> arecs;
    vector<string> aheader;
    loadRecords(aFile, arecs, aheader);
    if (o.header) for (size_t i = 0; i < aheader.size(); ++i) outLine(aheader[i]);
    vector<Hit> hits;
    for (size_t ai = 0; ai < arecs.size(); ++ai) {
        const BedRec &a = arecs[ai];
        collect(bsets, a.chrom(), a.start, a.end, hits);
        size_t k = 0;
        for (size_t j = 0; j < hits.size(); ++j) if (overlapsOK(a, *hits[j].rec, o)) hits[k++] = hits[j];
        hits.resize(k);
        long len = a.end - a.start;
        // build depth profile
        vector<long> depth;
        if (len == 0) depth.assign(2, 0);
        else depth.assign(len, 0);
        for (size_t j = 0; j < hits.size(); ++j) {
            const BedRec &b = *hits[j].rec;
            long s = a.start > b.start ? a.start : b.start;
            long e = a.end < b.end ? a.end : b.end;
            if (e > s) {
                for (long p = s; p < e; ++p) depth[p - a.start]++;
            }
        }
        long covered = 0;
        for (size_t j = 0; j < depth.size(); ++j) if (depth[j] > 0) covered++;
        double sizeD = (double)(depth.size());
        if (counts) {
            outLine(a.raw() + "\t" + num2str((long)hits.size()));
            continue;
        }
        if (mean) {
            double sum = 0;
            for (size_t j = 0; j < depth.size(); ++j) sum += (double)depth[j];
            double m = depth.empty() ? 0.0 : sum / sizeD;
            std::ostringstream ss; ss << std::setprecision(7) << std::fixed << m;
            outLine(a.raw() + "\t" + ss.str());
            continue;
        }
        if (d) {
            for (size_t j = 0; j < depth.size(); ++j)
                outLine(a.raw() + "\t" + num2str((long)(j+1)) + "\t" + num2str(depth[j]));
            continue;
        }
        if (hist) {
            map<long, long> h;
            for (size_t j = 0; j < depth.size(); ++j) h[depth[j]]++;
            for (map<long,long>::iterator it = h.begin(); it != h.end(); ++it) {
                double frac = depth.empty() ? 0.0 : (double)it->second / sizeD;
                std::ostringstream ss; ss << std::setprecision(7) << std::fixed << frac;
                outLine(a.raw() + "\t" + num2str(it->first) + "\t" + num2str(it->second) +
                        "\t" + num2str((long)depth.size()) + "\t" + ss.str());
            }
            continue;
        }
        double frac = depth.empty() ? 0.0 : (double)covered / sizeD;
        std::ostringstream ss; ss << std::setprecision(7) << std::fixed << frac;
        outLine(a.raw() + "\t" + num2str((long)hits.size()) + "\t" + num2str(covered) +
                "\t" + num2str((long)depth.size()) + "\t" + ss.str());
    }
    OUT.flush();
    return 0;
}

// ---------- map ----------
int cmd_map(int argc, char **argv) {
    BinOpts o;
    string aFile;
    vector<string> bFiles;
    vector<string> cols;   // column numbers as strings
    vector<string> ops;
    string delim = ",";
    int prec = 10;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("map"); }
        else if (arg == "-c") { if (i+1>=argc) bedFatal("Please specify a column for -c"); cols.clear(); splitList(argv[++i], cols); }
        else if (arg == "-o") { if (i+1>=argc) bedFatal("Please specify an operation for -o"); ops.clear(); splitList(argv[++i], ops); }
        else if (arg == "-delim") { if (i+1>=argc) bedFatal("Please specify a delimiter for -delim"); delim = argv[++i]; }
        else if (arg == "-prec") { if (i+1>=argc) bedFatal("Please specify a precision for -prec"); prec = atoi(argv[++i]); }
        else if (arg == "-a") { if (i+1 >= argc) bedFatal("No input file given. Exiting."); aFile = argv[++i]; }
        else if (arg == "-b") {
            if (i+1 >= argc) bedFatal("-b option given, but no database file specified.");
            ++i;
            while (i < argc && argv[i][0] != '-') bFiles.push_back(argv[i++]);
            --i;
        }
        else if (parseCommonOpt(arg, argc, argv, i, o)) {}
        else { fputs(HELP_map, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (aFile.empty()) { fputs(HELP_map, stderr); bedFatal("No input file given. Exiting."); }
    if (bFiles.empty()) { fputs(HELP_map, stderr); bedFatal("query and database files not specified."); }
    if (o.anyWhere && !o.fracASet) { fputs(HELP_map, stderr); bedFatal("-e must be used with -f."); }
    if (o.anyWhere && !o.fracBSet) o.fracB = 0.0;
    if (cols.empty()) cols.push_back("5");
    if (ops.empty()) ops.push_back("sum");
    // expand: if one col and many ops -> apply all ops to that col, etc.
    vector<int> colNums;
    vector<string> colOps;
    if (cols.size() == 1 && ops.size() > 1) {
        for (size_t i = 0; i < ops.size(); ++i) { colNums.push_back(atoi(cols[0].c_str())); colOps.push_back(ops[i]); }
    } else if (ops.size() == 1 && cols.size() > 1) {
        for (size_t i = 0; i < cols.size(); ++i) { colNums.push_back(atoi(cols[i].c_str())); colOps.push_back(ops[0]); }
    } else if (cols.size() == ops.size()) {
        for (size_t i = 0; i < cols.size(); ++i) { colNums.push_back(atoi(cols[i].c_str())); colOps.push_back(ops[i]); }
    } else {
        bedFatal("Please provide the same number of columns and operations.");
    }
    vector<FileBins> bsets;
    vector<vector<BedRec> > recsets;
    loadFiles(bFiles, bsets, recsets);
    vector<BedRec> arecs;
    vector<string> aheader;
    loadRecords(aFile, arecs, aheader);
    if (o.header) for (size_t i = 0; i < aheader.size(); ++i) outLine(aheader[i]);
    vector<Hit> hits;
    for (size_t ai = 0; ai < arecs.size(); ++ai) {
        const BedRec &a = arecs[ai];
        collect(bsets, a.chrom(), a.start, a.end, hits);
        size_t k = 0;
        for (size_t j = 0; j < hits.size(); ++j) if (overlapsOK(a, *hits[j].rec, o)) hits[k++] = hits[j];
        hits.resize(k);
        string out = a.raw();
        for (size_t c = 0; c < colNums.size(); ++c) {
            int col = colNums[c];
            vector<string> vals;
            for (size_t j = 0; j < hits.size(); ++j) {
                const BedRec &b = *hits[j].rec;
                string v = ((size_t)(col-1) < b.fields.size()) ? b.fields[col-1] : string(".");
                vals.push_back(v);
            }
            out += "\t" + applyNumOp(colOps[c], vals, delim, prec, col);
        }
        outLine(out);
    }
    OUT.flush();
    return 0;
}
