// ---------- closest ----------
struct CloseOpts {
    bool d, D, io, iu, id, fu, fd;
    string t;      // all | first | last
    string mdb;    // each | all
    int k;
    bool N;
    string Dorient;
    CloseOpts() : d(false), D(false), io(false), iu(false), id(false), fu(false), fd(false),
                  t("all"), mdb("each"), k(1), N(false) {}
};

struct CRec {
    const BedRec *rec;
    int file;
    int idx;
    long dist;
};

static long closestDist(const BedRec &a, const BedRec &b) {
    if (b.start < a.end && b.end > a.start) return 0;
    if (b.end <= a.start) return a.start - b.end;
    return b.start - a.end;
}

// per-chrom sorted cache for closest
struct CloseCache {
    vector<int> order;      // indices sorted by start
    vector<long> maxEnd;    // prefix max of end
};
static map<string, CloseCache> &cacheFor(const FileBins &fb, int f,
                                         map<int, map<string, CloseCache> > &caches) {
    return caches[f];
}

int cmd_closest(int argc, char **argv) {
    BinOpts o;
    CloseOpts co;
    string aFile;
    vector<string> bFiles;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("closest"); }
        else if (arg == "-d") co.d = true;
        else if (arg == "-D") { co.D = true; if (i+1 < argc && argv[i+1][0] != '-') co.Dorient = argv[++i]; }
        else if (arg == "-io") co.io = true;
        else if (arg == "-iu") co.iu = true;
        else if (arg == "-id") co.id = true;
        else if (arg == "-fu") co.fu = true;
        else if (arg == "-fd") co.fd = true;
        else if (arg == "-t") { if (i+1>=argc) bedFatal("Please specify a tie mode for -t"); co.t = argv[++i]; }
        else if (arg == "-mdb") { if (i+1>=argc) bedFatal("Please specify a mdb for -mdb"); co.mdb = argv[++i]; }
        else if (arg == "-k") { if (i+1>=argc) bedFatal("Please specify a value for -k"); co.k = atoi(argv[++i]); }
        else if (arg == "-N") co.N = true;
        else if (arg == "-a") { if (i+1 >= argc) bedFatal("No input file given. Exiting."); aFile = argv[++i]; }
        else if (arg == "-b") {
            if (i+1 >= argc) bedFatal("-b option given, but no database file specified.");
            ++i;
            while (i < argc && argv[i][0] != '-') bFiles.push_back(argv[i++]);
            --i;
        }
        else if (parseCommonOpt(arg, argc, argv, i, o)) {}
        else { fputs(HELP_closest, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (aFile.empty()) { fputs(HELP_closest, stderr); bedFatal("No input file given. Exiting."); }
    if (bFiles.empty()) { fputs(HELP_closest, stderr); bedFatal("query and database files not specified."); }
    if (co.iu || co.id || co.fu || co.fd) {
        if (!co.D) { fputs(HELP_closest, stderr); bedFatal("-D must be specified with -iu, -id, -fu, or -fd."); }
    }
    vector<FileBins> bsets;
    vector<vector<BedRec> > recsets;
    loadFiles(bFiles, bsets, recsets);
    // build sorted caches
    vector<map<string, CloseCache> > caches(bsets.size());
    for (size_t f = 0; f < bsets.size(); ++f) {
        for (map<string, ChromBins>::iterator it = bsets[f].byChrom.begin();
             it != bsets[f].byChrom.end(); ++it) {
            const vector<BedRec> &rs = it->second.recs;
            CloseCache &cc = caches[f][it->first];
            cc.order.resize(rs.size());
            for (size_t i = 0; i < rs.size(); ++i) cc.order[i] = (int)i;
            std::stable_sort(cc.order.begin(), cc.order.end(), [&](int x, int y) {
                if (rs[x].start != rs[y].start) return rs[x].start < rs[y].start;
                return x < y;
            });
            cc.maxEnd.resize(rs.size());
            long mx = -1;
            for (size_t i = 0; i < cc.order.size(); ++i) {
                mx = rs[cc.order[i]].end > mx ? rs[cc.order[i]].end : mx;
                cc.maxEnd[i] = mx;
            }
        }
    }
    vector<BedRec> arecs;
    vector<string> aheader;
    loadRecords(aFile, arecs, aheader);
    if (o.header) for (size_t i = 0; i < aheader.size(); ++i) outLine(aheader[i]);

    for (size_t ai = 0; ai < arecs.size(); ++ai) {
        const BedRec &a = arecs[ai];
        vector<CRec> cands;
        for (size_t f = 0; f < bsets.size(); ++f) {
            map<string, CloseCache>::iterator cit = caches[f].find(a.chrom());
            if (cit == caches[f].end()) continue;
            const vector<BedRec> &rs = bsets[f].byChrom[a.chrom()].recs;
            vector<int> &ord = cit->second.order;
            vector<long> &me = cit->second.maxEnd;
            // binary search for first start > a.end
            int lo = (int)ord.size();
            {
                int s = 0, e = (int)ord.size();
                while (s < e) { int m = (s+e)/2; if (rs[ord[m]].start <= a.end) s = m+1; else e = m; }
                lo = s;
            }
            long best = -1;
            // scan forward
            for (int p = lo; p < (int)ord.size(); ++p) {
                const BedRec &b = rs[ord[p]];
                long dist = closestDist(a, b);
                if (dist == 0) { best = 0; }
                else if (best < 0 || dist < best) best = dist;
                if (best >= 0 && b.start - a.end >= best && dist > 0) break;
            }
            // scan backward
            for (int p = lo-1; p >= 0; --p) {
                const BedRec &b = rs[ord[p]];
                long dist = closestDist(a, b);
                if (dist == 0) { if (best < 0) best = 0; }
                else if (best < 0 || dist < best) best = dist;
                if (best >= 0 && me[p] < a.start - best) break;
            }
            // collect candidates within best
            for (int p = 0; p < (int)ord.size(); ++p) {
                const BedRec &b = rs[ord[p]];
                if (b.end <= a.start - (best < 0 ? 0 : best) ) continue;
                if (b.start >= a.end + (best < 0 ? 0 : best) && b.start > a.end) continue;
                long dist = closestDist(a, b);
                if (best >= 0 && dist > best) continue;
                CRec cr; cr.rec = &b; cr.file = (int)f; cr.idx = ord[p]; cr.dist = dist;
                cands.push_back(cr);
            }
            if (co.mdb != "all") {
                // filter and report per database
                filterAndReportClosest(a, cands, co, o, bsets, recsets, bFiles, (int)f);
                cands.clear();
            }
        }
        if (co.mdb == "all") {
            filterAndReportClosest(a, cands, co, o, bsets, recsets, bFiles, -1);
        }
    }
    OUT.flush();
    return 0;
}
