static void collect(const vector<FileBins> &bsets, const string &chrom, long qs, long qe,
                    vector<Hit> &hits) {
    hits.clear();
    for (size_t f = 0; f < bsets.size(); ++f) {
        const ChromBins *cb = bsets[f].get(chrom);
        if (!cb) continue;
        cb->query(qs, qe, tmp);
        for (size_t j = 0; j < tmp.size(); ++j) {
            Hit h; h.file = (int)f; h.idx = tmp[j]; h.rec = &cb->recs[tmp[j]];
            hits.push_back(h);
        }
    }
}

// ---------- closest ----------
struct CloseOpts {
    bool d, D, io, iu, id, fu, fd;
    string t, mdb;
    int k;
    bool N;
    string Dorient;
    CloseOpts() : d(false), D(false), io(false), iu(false), id(false), fu(false), fd(false),
                  t("all"), mdb("each"), k(1), N(false) {}
};

struct CRec {
    const BedRec *rec;
    int file;
    int idx;
    long dist;
};

static long closestDist(const BedRec &a, const BedRec &b) {
    if (b.start < a.end && b.end > a.start) return 0;
    if (b.end <= a.start) return a.start - b.end;
    return b.start - a.end;
}

// determine whether b is "upstream" of a according to the -D orientation
static bool isUpstream(const BedRec &a, const BedRec &b, const string &orient) {
    bool bLower = (b.end <= a.start);
    bool bHigher = (b.start >= a.end);
    if (orient == "a") {
        // upstream means lower unless A is on the minus strand
        bool aMinus = a.hasStrand() && a.strand() == "-";
        return aMinus ? bHigher : bLower;
    } else if (orient == "b") {
        bool bMinus = b.hasStrand() && b.strand() == "-";
        return bMinus ? bLower : bHigher;
    }
    return bLower;
}

static bool closestFilter(const BedRec &a, const CRec &c, const CloseOpts &co, const BinOpts &o) {
    if (!overlapsOK(a, *c.rec, o)) return false;
    bool ov = (c.dist == 0);
    if (co.io && ov) return false;
    if (co.D) {
        bool up = isUpstream(a, *c.rec, co.Dorient);
        if (co.iu && up) return false;
        if (co.id && !up && !ov) return false;
        if (co.fu && !up) return false;
        if (co.fd && up) return false;
    }
    if (co.N) {
        // require a different name (4th column)
        string an = a.fields.size() > 3 ? a.fields[3] : string("");
        string bn = c.rec->fields.size() > 3 ? c.rec->fields[3] : string("");
        if (an == bn) return false;
    }
    return true;
}

static void reportClosest(const BedRec &a, const vector<CRec> &cands, const CloseOpts &co,
                          size_t nfieldsB) {
    if (cands.empty()) {
        string s = a.raw() + "\tnone";
        for (size_t i = 1; i < nfieldsB; ++i) s += "\t-1";
        if (co.d) s += "\t-1";
        outLine(s);
        return;
    }
    // find min distance
    long minD = cands[0].dist;
    for (size_t i = 1; i < cands.size(); ++i) if (cands[i].dist < minD) minD = cands[i].dist;
    vector<CRec> out;
    if (co.t == "all") {
        long thresh;
        if ((int)cands.size() <= co.k) thresh = cands.back().dist;
        else {
            vector<long> ds;
            for (size_t i = 0; i < cands.size(); ++i) ds.push_back(cands[i].dist);
            std::sort(ds.begin(), ds.end());
            thresh = ds[co.k - 1];
        }
        for (size_t i = 0; i < cands.size(); ++i) if (cands[i].dist <= thresh) out.push_back(cands[i]);
    } else if (co.t == "first") {
        for (size_t i = 0; i < cands.size(); ++i) if (cands[i].dist == minD) { out.push_back(cands[i]); break; }
    } else {
        for (int i = (int)cands.size()-1; i >= 0; --i) if (cands[i].dist == minD) { out.push_back(cands[i]); break; }
    }
    for (size_t i = 0; i < out.size(); ++i) {
        string s = a.raw() + "\t" + out[i].rec->raw();
        if (co.d) s += "\t" + num2str(out[i].dist);
        outLine(s);
    }
}

