        else if (arg == "-mdb") { if (i+1>=argc) bedFatal("Please specify a mdb for -mdb"); co.mdb = argv[++i]; }
        else if (arg == "-k") { if (i+1>=argc) bedFatal("Please specify a value for -k"); co.k = atoi(argv[++i]); }
        else if (arg == "-N") co.N = true;
        else if (arg == "-a") { if (i+1 >= argc) bedFatal("No input file given. Exiting."); aFile = argv[++i]; }
        else if (arg == "-b") {
            if (i+1 >= argc) bedFatal("-b option given, but no database file specified.");
            ++i;
            while (i < argc && argv[i][0] != '-') bFiles.push_back(argv[i++]);
            --i;
        }
        else if (parseCommonOpt(arg, argc, argv, i, o)) {}
        else { fputs(HELP_closest, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (aFile.empty()) { fputs(HELP_closest, stderr); bedFatal("No input file given. Exiting."); }
    if (bFiles.empty()) { fputs(HELP_closest, stderr); bedFatal("query and database files not specified."); }
    if (co.iu || co.id || co.fu || co.fd) {
        if (!co.D) { fputs(HELP_closest, stderr); bedFatal("-D must be specified with -iu, -id, -fu, or -fd."); }
    }
    if (o.anyWhere && !o.fracASet) { fputs(HELP_closest, stderr); bedFatal("-e must be used with -f."); }
