    size_t nfieldsB = recsets[0].empty() ? 3 : recsets[0][0].fields.size();

    vector<CRec> cands, kept;
    for (size_t ai = 0; ai < arecs.size(); ++ai) {
        const BedRec &a = arecs[ai];
        for (size_t f = 0; f < bsets.size(); ++f) {
            cands.clear();
            map<string, CC>::iterator cit = caches[f].find(a.chrom());
            if (cit != caches[f].end()) {
                const vector<BedRec> &rs = bsets[f].byChrom[a.chrom()].recs;
                vector<int> &ord = cit->second.order;
                vector<long> &me = cit->second.maxEnd;
                int lo = (int)ord.size();
                { int s = 0, e = (int)ord.size();
                  while (s < e) { int m = (s+e)/2; if (rs[ord[m]].start <= a.end) s = m+1; else e = m; }
                  lo = s; }
                long best = -1;
                for (int p = lo; p < (int)ord.size(); ++p) {
                    long dist = closestDist(a, rs[ord[p]]);
                    if (dist == 0) best = 0;
                    else if (best < 0 || dist < best) best = dist;
                    if (best >= 0 && rs[ord[p]].start - a.end > best) break;
                }
                for (int p = lo-1; p >= 0; --p) {
                    long dist = closestDist(a, rs[ord[p]]);
                    if (dist == 0) { if (best < 0) best = 0; }
                    else if (best < 0 || dist < best) best = dist;
                    if (best >= 0 && me[p] < a.start - best) break;
                }
                long lim = best < 0 ? 0 : best;
                for (int p = lo; p < (int)ord.size(); ++p) {
                    if (rs[ord[p]].start > a.end + lim && rs[ord[p]].start > a.end) break;
                    CRec cr; cr.rec = &rs[ord[p]]; cr.file = (int)f; cr.idx = ord[p];
                    cr.dist = closestDist(a, rs[ord[p]]);
                    if (best >= 0 && cr.dist > best) continue;
                    cands.push_back(cr);
                }
                for (int p = lo-1; p >= 0; --p) {
                    if (me[p] < a.start - lim) break;
                    CRec cr; cr.rec = &rs[ord[p]]; cr.file = (int)f; cr.idx = ord[p];
                    cr.dist = closestDist(a, rs[ord[p]]);
                    if (best >= 0 && cr.dist > best) continue;
                    cands.push_back(cr);
                }
            }
            kept.clear();
            for (size_t j = 0; j < cands.size(); ++j)
                if (closestFilter(a, cands[j], co, o)) kept.push_back(cands[j]);
            std::sort(kept.begin(), kept.end(), [](const CRec &x, const CRec &y) {
                if (x.dist != y.dist) return x.dist < y.dist;
                if (x.file != y.file) return x.file < y.file;
                return x.idx < y.idx;
            });
            if (co.mdb == "all") {
                // accumulate across databases: report later
                for (size_t j = 0; j < kept.size(); ++j) allCands.push_back(kept[j]);
            } else {
                reportClosest(a, kept, co, nfieldsB);
            }
        }
        if (co.mdb == "all") {
            std::sort(allCands.begin(), allCands.end(), [](const CRec &x, const CRec &y) {
                if (x.dist != y.dist) return x.dist < y.dist;
                if (x.file != y.file) return x.file < y.file;
                return x.idx < y.idx;
            });
            reportClosest(a, allCands, co, nfieldsB);
            allCands.clear();
        }
    }
    OUT.flush();
    return 0;
}
