    if (mode == "genome") {
        GENOME.load(gFile);
        std::stable_sort(order.begin(), order.end(), [&](int x, int y) {
            int ix = GENOME.index(recs[x].chrom()), iy = GENOME.index(recs[y].chrom());
            if (ix != iy) return ix < iy;
            if (recs[x].start != recs[y].start) return recs[x].start < recs[y].start;
            return recs[x].end < recs[y].end;
        });
    } else if (mode == "sizeA" || mode == "sizeD") {
        std::stable_sort(order.begin(), order.end(), [&](int x, int y) {
            long lx = recs[x].len(), ly = recs[y].len();
            if (lx != ly) return mode == "sizeA" ? lx < ly : lx > ly;
            return x < y;
        });
    } else if (mode == "chrThenSizeA" || mode == "chrThenSizeD") {
        std::stable_sort(order.begin(), order.end(), [&](int x, int y) {
            if (recs[x].chrom() != recs[y].chrom()) return recs[x].chrom() < recs[y].chrom();
            long lx = recs[x].len(), ly = recs[y].len();
            if (lx != ly) return mode == "chrThenSizeA" ? lx < ly : lx > ly;
            return x < y;
        });
    } else if (mode == "chrThenScoreA" || mode == "chrThenScoreD") {
        std::stable_sort(order.begin(), order.end(), [&](int x, int y) {
            if (recs[x].chrom() != recs[y].chrom()) return recs[x].chrom() < recs[y].chrom();
            long sx = recs[x].fields.size() > 4 ? atol(recs[x].fields[4].c_str()) : 0;
            long sy = recs[y].fields.size() > 4 ? atol(recs[y].fields[4].c_str()) : 0;
            if (sx != sy) return mode == "chrThenScoreA" ? sx < sy : sx > sy;
            return x < y;
        });
    } else {
        std::stable_sort(order.begin(), order.end(), [&](int x, int y) {
            if (recs[x].chrom() != recs[y].chrom()) return recs[x].chrom() < recs[y].chrom();
            if (recs[x].start != recs[y].start) return recs[x].start < recs[y].start;
            if (recs[x].end != recs[y].end) return recs[x].end < recs[y].end;
            return x < y;
        });
    }
    for (size_t i = 0; i < order.size(); ++i) outLine(recs[order[i]].raw());
    OUT.flush();
    return 0;
}

