static void clampStart(long &s) { if (s < 0) s = 0; }
static void clampEnd(long &e, const string &chrom) {
    if (GENOME.ok && GENOME.has(chrom)) { long sz = GENOME.size(chrom); if (e > sz) e = sz; }
}

static int runFlankSlop(int argc, char **argv, bool isFlank) {
    const char *helpName = isFlank ? "flank" : "slop";
    string inFile, gFile;
    long b = 0, l = -1, r = -1;
    bool pct = false, sw = false, header = false;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp(helpName); }
        else if (arg == "-i") { if (i+1>=argc) bedFatal("-i option given, but no input file specified."); inFile = argv[++i]; }
        else if (arg == "-g") { if (i+1>=argc) bedFatal("-g option given, but no genome file specified."); gFile = argv[++i]; }
        else if (arg == "-b") { if (i+1>=argc) bedFatal("-b option given, but no value specified."); b = atol(argv[++i]); }
        else if (arg == "-l") { if (i+1>=argc) bedFatal("-l option given, but no value specified."); l = atol(argv[++i]); }
        else if (arg == "-r") { if (i+1>=argc) bedFatal("-r option given, but no value specified."); r = atol(argv[++i]); }
        else if (arg == "-s") sw = true;
        else if (arg == "-pct") pct = true;
        else if (arg == "-header") header = true;
        else if (arg == "-nobuf") OUT.nobuf = true;
        else if (arg == "-iobuf") { if (i+1<argc) ++i; }
        else if (arg == "-bed") {}
        else { fputs(helpFor(helpName), stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (inFile.empty()) { fputs(helpFor(helpName), stderr); bedFatal("The following parameters are required: -i -g"); }
    if (gFile.empty()) { fputs(helpFor(helpName), stderr); bedFatal("The following parameters are required: -i -g"); }
    if (l < 0 && r < 0) { l = r = b; }
    if (l < 0) l = 0;
    if (r < 0) r = 0;
    GENOME.load(gFile);
    vector<BedRec> recs;
    vector<string> hdr;
    loadRecords(inFile, recs, hdr);
    if (header) for (size_t i = 0; i < hdr.size(); ++i) outLine(hdr[i]);
    for (size_t i = 0; i < recs.size(); ++i) {
        BedRec a = recs[i];
        long ll = l, rr = r;
        if (pct) {
            double len = (double)a.len();
            ll = (long)(ll * len);
            rr = (long)(rr * len);
        }
        if (sw && a.hasStrand() && a.strand() == "-") { long t = ll; ll = rr; rr = t; }
        if (isFlank) {
            long ls = a.start - ll; clampStart(ls);
            outLine(a.chrom() + "\t" + num2str(ls) + "\t" + num2str(a.start) + a.raw().substr(a.raw().find('\t') == string::npos ? a.raw().size() : 0));
            long re = a.end + rr; clampEnd(re, a.chrom());
            outLine(a.chrom() + "\t" + num2str(a.end) + "\t" + num2str(re) + extraFields(a));
        } else {
            long ls = a.start - ll; clampStart(ls);
            long re = a.end + rr; clampEnd(re, a.chrom());
            BedRec o = a; o.start = ls; o.end = re;
            outLine(o.chrom() + "\t" + num2str(ls) + "\t" + num2str(re) + restOfRecord(a));
        }
    }
    OUT.flush();
    return 0;
}

// helper: the extra fields of a record (everything after column 3)
string restOfRecord(const BedRec &a) {
    string s;
    for (size_t i = 3; i < a.fields.size(); ++i) s += "\t" + a.fields[i];
    return s;
}
