            if (recs[x].start != recs[y].start) return recs[x].start < recs[y].start;
            return recs[x].end < recs[y].end;
        });
    } else if (mode == "sizeA" || mode == "sizeD") {
        std::stable_sort(order.begin(), order.end(), [&](int x, int y) {
            long lx = recs[x].len(), ly = recs[y].len();
            if (lx != ly) return mode == "sizeA" ? lx < ly : lx > ly;
            return x < y;
        });
    } else if (mode == "chrThenSizeA" || mode == "chrThenSizeD") {
        std::stable_sort(order.begin(), order.end(), [&](int x, int y) {
            if (recs[x].chrom() != recs[y].chrom()) return recs[x].chrom() < recs[y].chrom();
            long lx = recs[x].len(), ly = recs[y].len();
            if (lx != ly) return mode == "chrThenSizeA" ? lx < ly : lx > ly;
            return x < y;
        });
    } else if (mode == "chrThenScoreA" || mode == "chrThenScoreD") {
        std::stable_sort(order.begin(), order.end(), [&](int x, int y) {
            if (recs[x].chrom() != recs[y].chrom()) return recs[x].chrom() < recs[y].chrom();
