    long clusterNum = 0;
    bool have = false;
    BedRec cur;
    for (size_t i = 0; i < recs.size(); ++i) {
        const BedRec &r = recs[i];
        bool canMerge = false;
        if (have && r.chrom() == cur.chrom()) {
            canMerge = (r.start <= cur.end + dist);
            if (canMerge && sameStrand) {
                if (!r.hasStrand() || !cur.hasStrand() || r.strand() != cur.strand()) canMerge = false;
            }
        }
        if (!canMerge) clusterNum++;
        outLine(r.raw() + "\t" + num2str(clusterNum));
        if (!canMerge) cur = r;
        else if (r.end > cur.end) cur.end = r.end;
        have = true;
    }
    OUT.flush();
    return 0;
}
