        FileBins fb; fb.build(recs);
        out.push_back(fb);
        recsets.push_back(recs);
    }
}
static void collect(const vector<FileBins> &bsets, const string &chrom, long qs, long qe,
                    vector<Hit> &hits) {
    hits.clear();
    for (size_t f = 0; f < bsets.size(); ++f) {
        const ChromBins *cb = bsets[f].get(chrom);
        if (!cb) continue;
        cb->query(qs, qe, tmp);
        for (size_t j = 0; j < tmp.size(); ++j) {
            Hit h; h.file = (int)f; h.idx = tmp[j]; h.rec = &cb->recs[tmp[j]];
            hits.push_back(h);
        }
    }
}
