    std::sort(hits.begin(), hits.end(), [](const Hit &x, const Hit &y) {
        if (x.rec->start != y.rec->start) return x.rec->start < y.rec->start;
        if (x.file != y.file) return x.file < y.file;
        return x.idx < y.idx;
    });
}

// ---------- subtract ----------
int cmd_subtract(int argc, char **argv) {
    BinOpts o;
    string aFile;
    vector<string> bFiles;
    bool A = false, N = false, wb = false, wo = false;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("subtract"); }
        else if (arg == "-A") A = true;
        else if (arg == "-N") N = true;
        else if (arg == "-wb") wb = true;
        else if (arg == "-wo") wo = true;
        else if (arg == "-a") { if (i+1 >= argc) bedFatal("No input file given. Exiting."); aFile = argv[++i]; }
        else if (arg == "-b") {
            if (i+1 >= argc) bedFatal("-b option given, but no database file specified.");
            ++i;
            while (i < argc && argv[i][0] != '-') bFiles.push_back(argv[i++]);
            --i;
        }
        else if (parseCommonOpt(arg, argc, argv, i, o)) {}
        else { fputs(HELP_subtract, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (aFile.empty()) { fputs(HELP_subtract, stderr); bedFatal("No input file given. Exiting."); }
    if (bFiles.empty()) { fputs(HELP_subtract, stderr); bedFatal("query and database files not specified."); }
    if (o.anyWhere && !o.fracASet) { fputs(HELP_subtract, stderr); bedFatal("-e must be used with -f."); }
    if (o.anyWhere && !o.fracBSet) o.fracB = 0.0;
    vector<FileBins> bsets;
    vector<vector<BedRec> > recsets;
    loadFiles(bFiles, bsets, recsets);
    vector<BedRec> arecs;
    vector<string> aheader;
    loadRecords(aFile, arecs, aheader);
    if (o.header) for (size_t i = 0; i < aheader.size(); ++i) outLine(aheader[i]);
    vector<Hit> hits;
    for (size_t ai = 0; ai < arecs.size(); ++ai) {
        const BedRec &a = arecs[ai];
        collect(bsets, a.chrom(), a.start, a.end, hits);
        size_t k = 0;
        for (size_t j = 0; j < hits.size(); ++j) if (overlapsOK(a, *hits[j].rec, o)) hits[k++] = hits[j];
        hits.resize(k);
        sortHits(hits);
        if (A || N) {
            bool drop = false;
            if (A) drop = !hits.empty();
            else {
                long sum = 0;
                for (size_t j = 0; j < hits.size(); ++j) sum += overlapBases(a, *hits[j].rec);
                double len = (double)a.len();
                if (len > 0 && (double)sum / len >= o.fracA) drop = true;
                else if (len <= 0 && sum > 0) drop = true;
            }
            if (!drop) {
                if (wo) {
                    for (size_t j = 0; j < hits.size(); ++j) {
                        long ov = overlapBases(a, *hits[j].rec);
                        if (ov < 0) ov = 0;
                        outLine(a.raw() + "\t" + hits[j].rec->raw() + "\t" + num2str(ov));
                    }
                    if (hits.empty()) reportA(a);
                } else reportA(a);
            }
            continue;
        }
        // subtract the overlapping portions
        vector<pair<long,long> > frags;
        long cur = a.start;
        for (size_t j = 0; j < hits.size(); ++j) {
            const BedRec &b = *hits[j].rec;
            long bs = b.start, be = b.end;
            if (be <= cur) continue;
            if (bs > a.end) break;
            if (bs > cur) frags.push_back(make_pair(cur, bs));
            if (be > cur) cur = be;
        }
        if (cur < a.end) frags.push_back(make_pair(cur, a.end));
        if (wb || wo) {
            for (size_t j = 0; j < hits.size(); ++j) {
                const BedRec &b = *hits[j].rec;
                for (size_t q = 0; q < frags.size(); ++q) {
                    string s = a.chrom() + "\t" + num2str(frags[q].first) + "\t" + num2str(frags[q].second) +
                               restOfRecord(a) + "\t" + b.raw();
                    if (wo) {
                        long ov = overlapBases(a, b);
                        if (ov < 0) ov = 0;
                        s += "\t" + num2str(ov);
                    }
                    outLine(s);
                }
            }
            if (hits.empty()) reportA(a);
            continue;
        }
        for (size_t q = 0; q < frags.size(); ++q)
            outLine(a.chrom() + "\t" + num2str(frags[q].first) + "\t" + num2str(frags[q].second) + restOfRecord(a));
    }
    OUT.flush();
    return 0;
}

