// ---------- multiinter ----------
static void multiUnion(vector<string> &paths, const string &hdr, bool emptyMode, const string &filler,
                       bool cluster, bool header, const vector<string> &names, const string &gFile)
{
    vector<vector<BedRec> > sets;
    vector<string> fhdrs;
    for (size_t i = 0; i < paths.size(); ++i) {
        vector<BedRec> recs; vector<string> h;
        loadRecords(paths[i], recs, h);
        if (cluster) {
            // merge overlapping intervals within the file
            vector<BedRec> merged;
            for (size_t j = 0; j < recs.size(); ++j) {
                if (!merged.empty() && merged.back().chrom() == recs[j].chrom() &&
                    recs[j].start <= merged.back().end) {
                    if (recs[j].end > merged.back().end) merged.back().end = recs[j].end;
                } else merged.push_back(recs[j]);
            }
            recs.swap(merged);
        }
        sets.push_back(recs);
        fhdrs.push_back(h.size() ? h[0] : string(""));
    }
    (void)fhdrs;
    map<string, vector<const BedRec*> > byChrom;
    vector<string> chromOrder;
    for (size_t i = 0; i < sets.size(); ++i)
        for (size_t j = 0; j < sets[i].size(); ++j) {
            const string &c = sets[i][j].chrom();
            if (byChrom.find(c) == byChrom.end()) chromOrder.push_back(c);
            byChrom[c].push_back(&sets[i][j]);
        }
    if (header) {
        string h = "chrom\tstart\tend";
        for (size_t i = 0; i < paths.size(); ++i) {
            string n = (i < names.size()) ? names[i] : paths[i];
            h += "\t" + n;
        }
        outLine(h);
    }
    for (size_t ci = 0; ci < chromOrder.size(); ++ci) {
        const string &c = chromOrder[ci];
        // build change points
        map<long, int> points;
        vector<vector<const BedRec*> > &v = byChrom[c];
        vector<vector<int> > idxByFile(paths.size());
        for (size_t j = 0; j < v.size(); ++j) {
            int f = -1;
            for (size_t i = 0; i < sets.size(); ++i) {
                // find which file this belongs to
                bool found = false;
                for (size_t k = 0; k < sets[i].size(); ++k) if (&sets[i][k] == v[j]) { f = (int)i; found = true; break; }
                if (found) break;
            }
            if (f < 0) continue;
            points[v[j]->start] = 1;
            points[v[j]->end] = 1;
            idxByFile[f].push_back((int)j);
        }
        // compute depth at each point
        vector<long> prevDepth(paths.size(), 0);
        vector<long> curDepth(paths.size(), 0);
        bool first = true;
        vector<pair<long,long> > regions;
        vector<vector<long> > depths;
        long prevPos = -1;
        for (map<long,int>::iterator it = points.begin(); it != points.end(); ++it) {
            long pos = it->first;
            // compute depths for the region [prevPos, pos)
            if (prevPos >= 0) {
                vector<long> d(paths.size(), 0);
                for (size_t i = 0; i < paths.size(); ++i)
                    for (size_t j = 0; j < idxByFile[i].size(); ++j) {
                        const BedRec *r = v[idxByFile[i][j]];
                        if (r->start <= prevPos && r->end > prevPos) d[i]++;
                    }
                regions.push_back(make_pair(prevPos, pos));
                depths.push_back(d);
            }
            prevPos = pos;
        }
        for (size_t i = 0; i < regions.size(); ++i) {
            bool any = false;
            string line = c + "\t" + num2str(regions[i].first) + "\t" + num2str(regions[i].second);
            for (size_t j = 0; j < depths[i].size(); ++j) {
                if (depths[i][j] > 0) any = true;
                line += "\t" + (depths[i][j] > 0 ? num2str(depths[i][j]) : filler);
            }
            if (any || emptyMode) outLine(line);
        }
    }
}

