        outLine(h);
    }
    for (size_t i = 0; i < sets.size(); ++i) {
        for (size_t j = 0; j < sets[i].size(); ++j) {
            const string &c = sets[i][j].chrom();
            if (byChrom.find(c) == byChrom.end()) chromOrder.push_back(c);
            EV e; e.start = sets[i][j].start; e.end = sets[i][j].end; e.file = (int)i;
            byChrom[c].push_back(e);
        }
    }
    for (size_t ci = 0; ci < chromOrder.size(); ++ci) {
        const string &c = chromOrder[ci];
        vector<EV> &evs = byChrom[c];
        std::set<long> pts;
        for (size_t j = 0; j < evs.size(); ++j) { pts.insert(evs[j].start); pts.insert(evs[j].end); }
        vector<long> ptv(pts.begin(), pts.end());
        for (size_t p = 0; p + 1 < ptv.size(); ++p) {
            long s = ptv[p], e = ptv[p+1];
            vector<long> depth(paths.size(), 0);
            bool any = false;
            for (size_t j = 0; j < evs.size(); ++j) {
                if (evs[j].start <= s && evs[j].end >= e) {
                    depth[evs[j].file]++;
                    any = true;
                }
            }
            if (any || emptyMode) {
                string line = c + "\\t" + num2str(s) + "\\t" + num2str(e);
                for (size_t f = 0; f < depth.size(); ++f)
                    line += "\\t" + (depth[f] > 0 ? num2str(depth[f]) : filler);
                outLine(line);
            }
        }
    }
}

int cmd_multiinter(int argc, char **argv) {
    vector<string> paths, names;
    bool header = false, emptyMode = false, cluster = false;
    string filler = "0", gFile;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help" || arg == "-examples") { toolHelp("multiinter"); }
        else if (arg == "-i") {
            ++i;
            while (i < argc && argv[i][0] != '-') paths.push_back(argv[i++]);
            --i;
        }
        else if (arg == "-names") { ++i; while (i < argc && argv[i][0] != '-') names.push_back(argv[i++]); --i; }
        else if (arg == "-header") header = true;
        else if (arg == "-empty") emptyMode = true;
        else if (arg == "-cluster") cluster = true;
        else if (arg == "-filler") { if (i+1>=argc) bedFatal("-filler option given, but no value specified."); filler = argv[++i]; }
        else if (arg == "-g") { if (i+1>=argc) bedFatal("-g option given, but no genome file specified."); gFile = argv[++i]; }
        else { fputs(HELP_multiinter, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (paths.empty()) die("missing file names (-i) to combine.");
    if (emptyMode && gFile.empty()) { fputs(HELP_multiinter, stderr); bedFatal("The -empty option requires the -g option."); }
    multiUnion(paths, emptyMode, filler, cluster, header, names, gFile);
    OUT.flush();
    return 0;
}

