        else if (arg == "-scale") { if (i+1>=argc) bedFatal("-scale option given, but no value specified."); bool ok=false; scale = parseDouble(argv[++i], ok); if (!ok) bedFatal("-scale option given, but no value specified."); }
        else if (arg == "-trackline") trackline = true;
        else if (arg == "-trackopts") { if (i+1<argc) ++i; }
        else { fputs(HELP_genomecov, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (inFile.empty()) { fputs(HELP_genomecov, stderr); bedFatal("The following parameters are required: -i -g"); }
    if (gFile.empty() && !ibam) { fputs(HELP_genomecov, stderr); bedFatal("The following parameters are required: -i -g"); }
    if (!ibam) GENOME.load(gFile);
    vector<BedRec> recs;
    vector<string> hdr;
    loadRecords(inFile, recs, hdr);
    // order of chromosomes: input order, then remaining genome chroms
    vector<string> order;
    map<string,int> seen;
    for (size_t i = 0; i < recs.size(); ++i) {
        const string &c = recs[i].chrom();
        if (!seen.count(c)) { seen[c] = 1; order.push_back(c); }
    }
    if (GENOME.ok) {
        for (size_t i = 0; i < GENOME.chroms.size(); ++i)
            if (!seen.count(GENOME.chroms[i])) { seen[GENOME.chroms[i]] = 1; order.push_back(GENOME.chroms[i]); }
    }
    // compute depth per chromosome
    long genomeSize = 0;
    map<string, vector<long> > depth;
    for (size_t i = 0; i < order.size(); ++i) {
        const string &c = order[i];
        long size = GENOME.ok ? GENOME.size(c) : 0;
        if (size < 0) size = 0;
        genomeSize += size;
        vector<long> dv(size > 0 ? size : 0, 0);
        for (size_t j = 0; j < recs.size(); ++j) {
            if (recs[j].chrom() != c) continue;
            if (!strand.empty()) {
                if (!recs[j].hasStrand() || recs[j].strand() != strand) continue;
            }
            long s = recs[j].start, e = recs[j].end;
            if (s < 0) s = 0;
            if (size > 0 && e > size) e = size;
            if (e > s) for (long p = s; p < e; ++p) dv[p]++;
        }
        depth[c] = dv;
    }
    if (d) {
        for (size_t i = 0; i < order.size(); ++i) {
            const string &c = order[i];
            vector<long> &dv = depth[c];
            for (size_t p = 0; p < dv.size(); ++p) {
                long dep = dv[p];
                if (dz && dep == 0) continue;
                double v = (double)dep * scale;
                outLine(c + "\t" + num2str(dz ? (long)p : (long)(p+1)) + "\t" + fmt6(v));
            }
        }
        OUT.flush();
        return 0;
    }
    if (bg) {
        for (size_t i = 0; i < order.size(); ++i) {
            const string &c = order[i];
            vector<long> &dv = depth[c];
            long p = 0;
            while (p < (long)dv.size()) {
                long dep = dv[p];
                long q = p;
                while (q < (long)dv.size() && dv[q] == dep) q++;
                if (dep != 0 || bga) {
                    double v = (double)dep * scale;
                    string vs;
                    if (scale == 1.0) vs = num2str((long)v);
                    else vs = fmt6(v);
                    outLine(c + "\t" + num2str(p) + "\t" + num2str(q) + "\t" + vs);
                }
                p = q;
            }
            if (bga && dv.empty()) {
                long size = GENOME.ok ? GENOME.size(c) : 0;
                outLine(c + "\t0\t" + num2str(size) + "\t0");
            }
        }
        OUT.flush();
        return 0;
    }
    // histogram
    for (size_t i = 0; i < order.size(); ++i) {
        const string &c = order[i];
        vector<long> &dv = depth[c];
        long size = GENOME.ok ? GENOME.size(c) : 0;
        if (dv.empty() && size == 0) {
            outLine(c + "\t0\t0\t0\t0");
            continue;
        }
        map<long,long> h;
        for (size_t p = 0; p < dv.size(); ++p) {
            long dep = dv[p];
            if (maxDepth >= 0 && dep > maxDepth) dep = maxDepth;
            h[dep]++;
        }
        for (map<long,long>::iterator it = h.begin(); it != h.end(); ++it) {
            double frac = dv.empty() ? 0.0 : (double)it->second / (double)dv.size();
            outLine(c + "\t" + num2str(it->first) + "\t" + num2str(it->second) + "\t" +
                    num2str((long)dv.size()) + "\t" + fmt6(frac));
        }
    }
    // genome summary
    map<long,long> gh;
    for (size_t i = 0; i < order.size(); ++i) {
        vector<long> &dv = depth[order[i]];
        for (size_t p = 0; p < dv.size(); ++p) {
            long dep = dv[p];
            if (maxDepth >= 0 && dep > maxDepth) dep = maxDepth;
            gh[dep]++;
        }
    }
    for (map<long,long>::iterator it = gh.begin(); it != gh.end(); ++it) {
        double frac = genomeSize > 0 ? (double)it->second / (double)genomeSize : 0.0;
        outLine("genome\t" + num2str(it->first) + "\t" + num2str(it->second) + "\t" +
                num2str(genomeSize) + "\t" + fmt6(frac));
    }
    OUT.flush();
    return 0;
}

