            ivals.push_back(make_pair(recs[i].chrom(), make_pair(recs[i].start, recs[i].end)));
    } else {
        fputs(HELP_makewindows, stderr);
        bedFatal("Please provide either -g or -b.");
    }
    for (size_t i = 0; i < ivals.size(); ++i) {
        const string &c = ivals[i].first;
        long start = ivals[i].second.first, end = ivals[i].second.second;
        long len = end - start;
        if (n > 0) {
            long step = (len + n - 1) / n;
            if (step < 1) step = 1;
            long wnum = 1;
            for (long p = start; p < end; p += step) {
                long we = p + step;
                if (we > end) we = end;
                long winNum = reverse ? (long)((p - start) / step) + 1 : wnum;
                string name;
                if (idMode == "winnum") name = num2str(winNum);
                else if (idMode == "srcwinnum") {
                    string src = (bFile.size() && i < ivals.size()) ? "" : "";
                    name = "" ;
                    name = num2str(winNum);
                    if (!src.empty()) name = src + "_" + name;
                }
                string out = c + "\t" + num2str(p) + "\t" + num2str(we);
                if (idMode == "winnum" || idMode == "srcwinnum") out += "\t" + name;
                else if (idMode == "src") {
                    // source name comes from the record; handled below
                }
                outLine(out);
                wnum++;
                if (reverse) winNum = wnum;
            }
        } else if (w > 0) {
            long step = s > 0 ? s : w;
            long wnum = 1;
            for (long p = start; p < end; p += step) {
                long we = p + w;
                if (we > end) we = end;
                string out = c + "\t" + num2str(p) + "\t" + num2str(we);
                if (idMode == "winnum") out += "\t" + num2str(wnum);
                outLine(out);
                wnum++;
            }
        } else {
            fputs(HELP_makewindows, stderr);
            bedFatal("Please provide either -w or -n.");
        }
    }
    OUT.flush();
    return 0;
}
