// ---------- genomecov ----------
int cmd_genomecov(int argc, char **argv) {
    string inFile, gFile;
    bool ibam = false, d = false, dz = false, bg = false, bga = false, split = false;
    bool trackline = false;
    double scale = 1.0;
    long maxDepth = -1;
    string strand;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("genomecov"); }
