        if (!seen.count(c)) { seen[c] = 1; order.push_back(c); }
    }
    if (GENOME.ok) {
        for (size_t i = 0; i < GENOME.chroms.size(); ++i)
            if (!seen.count(GENOME.chroms[i])) { seen[GENOME.chroms[i]] = 1; order.push_back(GENOME.chroms[i]); }
    }
    // compute depth per chromosome
    long genomeSize = 0;
    map<string, vector<long> > depth;
    for (size_t i = 0; i < order.size(); ++i) {
        const string &c = order[i];
        long size = GENOME.ok ? GENOME.size(c) : 0;
        if (size < 0) size = 0;
        genomeSize += size;
        vector<long> dv(size > 0 ? size : 0, 0);
        for (size_t j = 0; j < recs.size(); ++j) {
            if (recs[j].chrom() != c) continue;
            if (!strand.empty()) {
                if (!recs[j].hasStrand() || recs[j].strand() != strand) continue;
            }
            long s = recs[j].start, e = recs[j].end;
            if (s < 0) s = 0;
            if (size > 0 && e > size) e = size;
            if (e > s) for (long p = s; p < e; ++p) dv[p]++;
        }
        depth[c] = dv;
    }
    if (d) {
        for (size_t i = 0; i < order.size(); ++i) {
            const string &c = order[i];
            vector<long> &dv = depth[c];
            for (size_t p = 0; p < dv.size(); ++p) {
                long dep = dv[p];
                if (dz && dep == 0) continue;
                double v = (double)dep * scale;
                outLine(c + "\t" + num2str(dz ? (long)p : (long)(p+1)) + "\t" + fmt6(v));
            }
        }
        OUT.flush();
        return 0;
    }
    if (bg) {
        for (size_t i = 0; i < order.size(); ++i) {
            const string &c = order[i];
            vector<long> &dv = depth[c];
            long p = 0;
            while (p < (long)dv.size()) {
                long dep = dv[p];
                long q = p;
                while (q < (long)dv.size() && dv[q] == dep) q++;
                if (dep != 0 || bga) {
                    double v = (double)dep * scale;
                    string vs;
                    if (scale == 1.0) vs = num2str((long)v);
                    else vs = fmt6(v);
                    outLine(c + "\t" + num2str(p) + "\t" + num2str(q) + "\t" + vs);
                }
                p = q;
            }
            if (bga && dv.empty()) {
                long size = GENOME.ok ? GENOME.size(c) : 0;
                outLine(c + "\t0\t" + num2str(size) + "\t0");
            }
        }
        OUT.flush();
        return 0;
    }
    // histogram
    for (size_t i = 0; i < order.size(); ++i) {
        const string &c = order[i];
        vector<long> &dv = depth[c];
        long size = GENOME.ok ? GENOME.size(c) : 0;
        if (dv.empty() && size == 0) {
            outLine(c + "\t0\t0\t0\t0");
            continue;
        }
        map<long,long> h;
        for (size_t p = 0; p < dv.size(); ++p) {
            long dep = dv[p];
            if (maxDepth >= 0 && dep > maxDepth) dep = maxDepth;
            h[dep]++;
        }
        for (map<long,long>::iterator it = h.begin(); it != h.end(); ++it) {
            double frac = dv.empty() ? 0.0 : (double)it->second / (double)dv.size();
            outLine(c + "\t" + num2str(it->first) + "\t" + num2str(it->second) + "\t" +
                    num2str((long)dv.size()) + "\t" + fmt6(frac));
        }
    }
    // genome summary
    map<long,long> gh;
    for (size_t i = 0; i < order.size(); ++i) {
        vector<long> &dv = depth[order[i]];
        for (size_t p = 0; p < dv.size(); ++p) {
            long dep = dv[p];
            if (maxDepth >= 0 && dep > maxDepth) dep = maxDepth;
            gh[dep]++;
        }
    }
    for (map<long,long>::iterator it = gh.begin(); it != gh.end(); ++it) {
        double frac = genomeSize > 0 ? (double)it->second / (double)genomeSize : 0.0;
        outLine("genome\t" + num2str(it->first) + "\t" + num2str(it->second) + "\t" +
                num2str(genomeSize) + "\t" + fmt6(frac));
    }
    OUT.flush();
    return 0;
}

// ---------- makewindows ----------
int cmd_makewindows(int argc, char **argv) {
    string gFile, bFile, idMode;
    long w = -1, s = -1, n = -1;
    bool reverse = false;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("makewindows"); }
        else if (arg == "-g") { if (i+1>=argc) bedFatal("-g option given, but no genome file specified."); gFile = argv[++i]; }
        else if (arg == "-b") { if (i+1>=argc) bedFatal("-b option given, but no bed file specified."); bFile = argv[++i]; }
        else if (arg == "-w") { if (i+1>=argc) bedFatal("-w option given, but no value specified."); w = atol(argv[++i]); }
        else if (arg == "-s") { if (i+1>=argc) bedFatal("-s option given, but no value specified."); s = atol(argv[++i]); }
        else if (arg == "-n") { if (i+1>=argc) bedFatal("-n option given, but no value specified."); n = atol(argv[++i]); }
        else if (arg == "-i") { if (i+1>=argc) bedFatal("-i option given, but no value specified."); idMode = argv[++i]; }
        else if (arg == "-reverse") reverse = true;
        else { fputs(HELP_makewindows, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    vector<pair<string, pair<long,long> > > ivals;
    if (!gFile.empty()) {
        GENOME.load(gFile);
        for (size_t i = 0; i < GENOME.chroms.size(); ++i)
            ivals.push_back(make_pair(GENOME.chroms[i], make_pair((long)0, GENOME.size(GENOME.chroms[i]))));
    } else if (!bFile.empty()) {
        vector<BedRec> recs; vector<string> h;
        loadRecords(bFile, recs, h);
        for (size_t i = 0; i < recs.size(); ++i)
            ivals.push_back(make_pair(recs[i].chrom(), make_pair(recs[i].start, recs[i].end)));
    } else {
        fputs(HELP_makewindows, stderr);
        bedFatal("Please provide either -g or -b.");
    }
    for (size_t i = 0; i < ivals.size(); ++i) {
        const string &c = ivals[i].first;
        long start = ivals[i].second.first, end = ivals[i].second.second;
        long len = end - start;
        if (n > 0) {
            long step = (len + n - 1) / n;
            if (step < 1) step = 1;
            long wnum = 1;
            for (long p = start; p < end; p += step) {
                long we = p + step;
                if (we > end) we = end;
                long winNum = reverse ? (long)((p - start) / step) + 1 : wnum;
                string name;
                if (idMode == "winnum") name = num2str(winNum);
                else if (idMode == "srcwinnum") {
                    string src = (bFile.size() && i < ivals.size()) ? "" : "";
                    name = "" ;
                    name = num2str(winNum);
                    if (!src.empty()) name = src + "_" + name;
                }
                string out = c + "\t" + num2str(p) + "\t" + num2str(we);
                if (idMode == "winnum" || idMode == "srcwinnum") out += "\t" + name;
                else if (idMode == "src") {
                    // source name comes from the record; handled below
                }
                outLine(out);
                wnum++;
                if (reverse) winNum = wnum;
            }
        } else if (w > 0) {
            long step = s > 0 ? s : w;
            long wnum = 1;
            for (long p = start; p < end; p += step) {
                long we = p + w;
                if (we > end) we = end;
                string out = c + "\t" + num2str(p) + "\t" + num2str(we);
                if (idMode == "winnum") out += "\t" + num2str(wnum);
                outLine(out);
                wnum++;
            }
        } else {
            fputs(HELP_makewindows, stderr);
            bedFatal("Please provide either -w or -n.");
        }
    }
    OUT.flush();
    return 0;
}
