        if (full) {
            for (size_t i = 0; i < fr.fields.size(); ++i) { if (i) out += "\t"; out += fr.fields[i]; }
        } else {
            for (size_t i = 0; i < gnums.size(); ++i) {
                int c = gnums[i];
                if (i) out += "\t";
                out += ((size_t)(c-1) < fr.fields.size()) ? fr.fields[c-1] : string(".");
