// ---------- expand ----------
int cmd_expand(int argc, char **argv) {
    string inFile;
    vector<string> cols;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("expand"); }
        else if (arg == "-i") { if (i+1>=argc) bedFatal("-i option given, but no input file specified."); inFile = argv[++i]; }
        else if (arg == "-c") { if (i+1>=argc) bedFatal("-c option given, but no columns specified."); splitList(argv[++i], cols); }
        else { fputs(HELP_expand, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (cols.empty()) bedFatal("Please provide -c COLS.");
    if (inFile.empty()) inFile = "-";
    vector<BedRec> recs;
    vector<string> hdr;
    loadRecords(inFile, recs, hdr);
    vector<int> cnums;
    for (size_t i = 0; i < cols.size(); ++i) cnums.push_back(atoi(cols[i].c_str()));
    for (size_t i = 0; i < recs.size(); ++i) {
        const BedRec &r = recs[i];
        size_t n = 0;
        bool first = true;
        for (size_t c = 0; c < cnums.size(); ++c) {
            int col = cnums[c];
            vector<string> vals;
            if ((size_t)(col-1) < r.fields.size()) splitList(r.fields[col-1], vals);
            if (first) { n = vals.size(); first = false; }
            else if (vals.size() != n) bedFatal("Unequal number of values in -c columns.");
        }
        for (size_t k = 0; k < n; ++k) {
            string out;
            for (size_t f = 0; f < r.fields.size(); ++f) {
                bool isCol = false; size_t ci = 0;
                for (size_t c = 0; c < cnums.size(); ++c) if ((size_t)cnums[c]-1 == f) { isCol = true; ci = c; break; }
                if (f) out += "\t";
                if (isCol) {
                    vector<string> vals;
                    splitList(r.fields[f], vals);
                    out += vals[k];
                } else out += r.fields[f];
            }
            outLine(out);
        }
    }
    OUT.flush();
    return 0;
}

// ---------- split ----------
int cmd_split(int argc, char **argv) {
    string inFile, prefix = "_split.", algo = "size";
    long n = 0;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help" || arg == "-help") {
            fputs(HELP_split, stdout);
            fflush(stdout);
            return 0;
        }
        else if (arg == "--version" || arg == "-v") { printf("bedtools split %s\n", BT_VERSION); fflush(stdout); return 0; }
        else if (arg == "-i" || arg == "--input") { if (i+1>=argc) bedFatal("Error: num_chunks==0."); inFile = argv[++i]; }
        else if (arg == "-n" || arg == "--number") { if (i+1>=argc) bedFatal("Error: num_chunks==0."); n = atol(argv[++i]); }
        else if (arg == "-p" || arg == "--prefix") { if (i+1>=argc) bedFatal("Error: num_chunks==0."); prefix = argv[++i]; }
        else if (arg == "-a" || arg == "--algorithm") { if (i+1>=argc) bedFatal("Error: num_chunks==0."); algo = argv[++i]; }
        else { fputs(HELP_split, stdout); fflush(stdout); return 0; }
    }
    if (n <= 0) { fprintf(stderr, "Error: num_chunks==0.\n\n"); return 0; }
    if (inFile.empty()) { fprintf(stderr, "Error: num_chunks==0.\n\n"); return 0; }
    vector<BedRec> recs;
    vector<string> hdr;
    loadRecords(inFile, recs, hdr);
    size_t chunks = (size_t)n;
    vector<vector<BedRec> > groups(chunks);
    vector<long> sizes(chunks, 0);
    if (algo == "simple") {
        size_t per = (recs.size() + chunks - 1) / chunks;
        for (size_t i = 0; i < recs.size(); ++i) {
            size_t g = i / per;
            if (g >= chunks) g = chunks - 1;
            groups[g].push_back(recs[i]);
            sizes[g] += recs[i].len();
        }
    } else {
        // greedy: assign records (in order) to the chunk with the fewest bases
        for (size_t i = 0; i < recs.size(); ++i) {
            size_t best = 0;
            for (size_t g = 1; g < chunks; ++g) if (sizes[g] < sizes[best]) best = g;
            groups[best].push_back(recs[i]);
            sizes[best] += recs[i].len();
        }
    }
    for (size_t g = 0; g < chunks; ++g) {
        char buf[512];
        snprintf(buf, sizeof(buf), "%s%05zu.bed", prefix.c_str(), g+1);
        FILE *fp = fopen(buf, "w");
        for (size_t j = 0; j < groups[g].size(); ++j) fprintf(fp, "%s\n", groups[g][j].raw().c_str());
        fclose(fp);
        printf("%s\t%ld\t%zu\n", buf, sizes[g], groups[g].size());
    }
    fflush(stdout);
    return 0;
}

