// ---------- shuffle ----------
int cmd_shuffle(int argc, char **argv) {
    string inFile, gFile, exclFile, inclFile;
    long seed = -1;
    bool chrom = false;
    double f = 1e-9;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("shuffle"); }
        else if (arg == "-i") { if (i+1>=argc) bedFatal("-i option given, but no input file specified."); inFile = argv[++i]; }
        else if (arg == "-g") { if (i+1>=argc) bedFatal("-g option given, but no genome file specified."); gFile = argv[++i]; }
        else if (arg == "-excl") { if (i+1>=argc) bedFatal("-excl option given, but no file specified."); exclFile = argv[++i]; }
        else if (arg == "-incl") { if (i+1>=argc) bedFatal("-incl option given, but no file specified."); inclFile = argv[++i]; }
        else if (arg == "-chrom") chrom = true;
        else if (arg == "-seed") { if (i+1>=argc) bedFatal("-seed option given, but no value specified."); seed = atol(argv[++i]); }
        else if (arg == "-f") { if (i+1>=argc) bedFatal("-f option given, but no value specified."); bool ok=false; f = parseDouble(argv[++i], ok); }
        else if (arg == "-nobuf") OUT.nobuf = true;
        else if (arg == "-iobuf") { if (i+1<argc) ++i; }
        else { fputs(HELP_shuffle, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (inFile.empty() || gFile.empty()) { fputs(HELP_shuffle, stderr); bedFatal("The following parameters are required: -i -g"); }
    if (seed >= 0) srand((unsigned)seed); else srand((unsigned)time(NULL));
    GENOME.load(gFile);
    vector<BedRec> recs;
    vector<string> hdr;
    loadRecords(inFile, recs, hdr);
    vector<pair<long,long> > excl;
    if (!exclFile.empty()) {
        vector<BedRec> er; vector<string> h;
        loadRecords(exclFile, er, h);
        for (size_t i = 0; i < er.size(); ++i) excl.push_back(std::make_pair(er[i].start, er[i].end));
    }
    vector<pair<string,long> > incl;
    if (!inclFile.empty()) {
        vector<BedRec> ir; vector<string> h;
        loadRecords(inclFile, ir, h);
        for (size_t i = 0; i < ir.size(); ++i) incl.push_back(std::make_pair(0, ir[i].len()));
        // choose a random interval weighted by length
        for (size_t i = 0; i < recs.size(); ++i) {
            long len = recs[i].len();
            long total = 0;
            for (size_t j = 0; j < ir.size(); ++j) total += (ir[j].end - ir[j].start) > len ? (ir[j].end - ir[j].start) - len + 1 : 0;
            long r = rand() % (total > 0 ? total : 1);
            for (size_t j = 0; j < ir.size(); ++j) {
                long avail = (ir[j].end - ir[j].start) - len + 1;
                if (avail <= 0) continue;
                if (r < avail) {
                    BedRec o = recs[i];
                    o.start = ir[j].start + r; o.end = o.start + len;
                    outLine(o.raw());
                    break;
                }
                r -= avail;
            }
        }
        OUT.flush();
        return 0;
    }
    // genome-wide shuffle
    vector<long> cum;
    long total = 0;
    for (size_t i = 0; i < GENOME.chroms.size(); ++i) {
        total += GENOME.size(GENOME.chroms[i]);
        cum.push_back(total);
    }
    for (size_t i = 0; i < recs.size(); ++i) {
        BedRec o = recs[i];
        long len = o.len();
        for (int tries = 0; tries < 1000; ++tries) {
            long r = rand() % (total > 0 ? total : 1);
            size_t ci = 0;
            while (ci < cum.size() && r >= cum[ci]) ci++;
            if (ci >= cum.size()) ci = cum.size() - 1;
            long csize = GENOME.size(GENOME.chroms[ci]);
            long cs = (ci == 0) ? 0 : cum[ci-1];
            long maxStart = csize - len;
            if (maxStart < 0) continue;
            long ns = cs + (rand() % (maxStart + 1));
            bool bad = false;
            if (!excl.empty() && GENOME.chroms[ci] == o.chrom()) {
                for (size_t j = 0; j < excl.size(); ++j) {
                    long s = ns > excl[j].first ? ns : excl[j].first;
                    long e = (ns+len) < excl[j].second ? (ns+len) : excl[j].second;
                    if (e > s && (double)(e-s)/(double)len > f) { bad = true; break; }
                }
            }
            if (bad) continue;
            o.chrom_str = GENOME.chroms[ci];
            o.fields[0] = o.chrom_str;
            o.start = ns; o.end = ns + len;
            outLine(o.raw());
            break;
        }
    }
    OUT.flush();
    return 0;
}

// ---------- random ----------
int cmd_random(int argc, char **argv) {
    string gFile;
    long l = 100, n = 1000000, seed = -1;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("random"); }
        else if (arg == "-g") { if (i+1>=argc) bedFatal("-g option given, but no genome file specified."); gFile = argv[++i]; }
        else if (arg == "-l") { if (i+1>=argc) bedFatal("-l option given, but no value specified."); l = atol(argv[++i]); }
        else if (arg == "-n") { if (i+1>=argc) bedFatal("-n option given, but no value specified."); n = atol(argv[++i]); }
        else if (arg == "-seed") { if (i+1>=argc) bedFatal("-seed option given, but no value specified."); seed = atol(argv[++i]); }
        else { fputs(HELP_random, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (gFile.empty()) { fputs(HELP_random, stderr); bedFatal("The following parameters are required: -g"); }
    if (seed >= 0) srand((unsigned)seed); else srand((unsigned)time(NULL));
    GENOME.load(gFile);
    vector<long> cum;
    long total = 0;
    for (size_t i = 0; i < GENOME.chroms.size(); ++i) {
        total += GENOME.size(GENOME.chroms[i]);
        cum.push_back(total);
    }
    for (long i = 0; i < n; ++i) {
        long r = rand() % (total > 0 ? total : 1);
        size_t ci = 0;
        while (ci < cum.size() && r >= cum[ci]) ci++;
        if (ci >= cum.size()) ci = cum.size() - 1;
        long csize = GENOME.size(GENOME.chroms[ci]);
        long cs = (ci == 0) ? 0 : cum[ci-1];
        long maxStart = csize - l;
        if (maxStart < 0) { i--; continue; }
        long ns = cs + (rand() % (maxStart + 1));
        outLine(GENOME.chroms[ci] + "\t" + num2str(ns) + "\t" + num2str(ns + l));
    }
    OUT.flush();
    return 0;
}

// ---------- bed12tobed6 ----------
int cmd_bed12tobed6(int argc, char **argv) {
    string inFile;
    bool n = false;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("bed12tobed6"); }
        else if (arg == "-i") { if (i+1>=argc) bedFatal("-i option given, but no input file specified."); inFile = argv[++i]; }
        else if (arg == "-n") n = true;
        else if (arg == "-nobuf") OUT.nobuf = true;
        else if (arg == "-iobuf") { if (i+1<argc) ++i; }
        else if (arg == "-bed") {}
        else { fputs(HELP_bed12tobed6, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (inFile.empty()) { fputs(HELP_bed12tobed6, stderr); bedFatal("The following parameters are required: -i"); }
    vector<BedRec> recs;
    vector<string> hdr;
    loadRecords(inFile, recs, hdr);
    for (size_t i = 0; i < recs.size(); ++i) {
        const BedRec &r = recs[i];
        if (r.fields.size() < 12) continue;
        long nblocks = atol(r.fields[9].c_str());
        vector<long> bs, be;
        splitList(r.fields[10], bs);
        splitList(r.fields[11], be);
        string name = r.fields.size() > 3 ? r.fields[3] : string("");
        string strand = r.fields.size() > 5 ? r.fields[5] : string(".");
        for (long b = 0; b < nblocks && b < (long)bs.size(); ++b) {
            long s = r.start + bs[b], e = r.start + be[b];
            long score = n ? (b+1) : (r.fields.size() > 4 ? atol(r.fields[4].c_str()) : 0);
            outLine(r.chrom() + "\t" + num2str(s) + "\t" + num2str(e) + "\t" + name + "\t" + num2str(score) + "\t" + strand);
        }
    }
    OUT.flush();
    return 0;
}

