        else if (arg == "-nobuf") OUT.nobuf = true;
        else if (arg == "-iobuf") { if (i+1<argc) ++i; }
        else if (arg == "-bed") {}
        else { fputs(HELP_bed12tobed6, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
