        string name = r.fields.size() > 3 ? r.fields[3] : string("");
        string strand = r.fields.size() > 5 ? r.fields[5] : string(".");
        for (long b = 0; b < nblocks && b < (long)bs.size(); ++b) {
            long s = r.start + bs[b], e = r.start + be[b];
            long score = n ? (b+1) : (r.fields.size() > 4 ? atol(r.fields[4].c_str()) : 0);
            outLine(r.chrom() + "\t" + num2str(s) + "\t" + num2str(e) + "\t" + name + "\t" + num2str(score) + "\t" + strand);
        }
    }
