// ---------- igv ----------
int cmd_igv(int argc, char **argv) {
    string inFile, path = "./", sess, sortMode;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("igv"); }
        else if (arg == "-i") { if (i+1>=argc) bedFatal("-i option given, but no input file specified."); inFile = argv[++i]; }
        else if (arg == "-path") { if (i+1<argc) path = argv[++i]; }
        else if (arg == "-sess") { if (i+1<argc) sess = argv[++i]; }
        else if (arg == "-sort") { if (i+1<argc) sortMode = argv[++i]; }
        else { fputs(HELP_igv, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (inFile.empty()) { fputs(HELP_igv, stderr); bedFatal("The following parameters are required: -i"); }
    vector<BedRec> recs;
    vector<string> hdr;
    loadRecords(inFile, recs, hdr);
    outLine("new");
    if (!sess.empty()) outLine("load " + sess);
    for (size_t i = 0; i < recs.size(); ++i) {
        const BedRec &r = recs[i];
        string pos = r.chrom() + ":" + num2str(r.start) + "-" + num2str(r.end);
        outLine("goto " + pos);
        outLine("snapshot " + path + r.chrom() + "_" + num2str(r.start) + ".png");
    }
    OUT.flush();
    return 0;
}

// ---------- summary ----------
int cmd_summary(int argc, char **argv) {
    string inFile, gFile;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("summary"); }
        else if (arg == "-i") { if (i+1>=argc) bedFatal("-i option given, but no input file specified."); inFile = argv[++i]; }
        else if (arg == "-g") { if (i+1>=argc) bedFatal("-g option given, but no genome file specified."); gFile = argv[++i]; }
        else { fputs(HELP_summary, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (gFile.empty()) { fputs(HELP_summary, stderr); bedFatal("no -g genome file provided."); }
    if (inFile.empty()) { fputs(HELP_summary, stderr); bedFatal("The following parameters are required: -i -g"); }
    GENOME.load(gFile);
    vector<BedRec> recs;
    vector<string> hdr;
    loadRecords(inFile, recs, hdr);
    map<string, vector<long> > byChrom;
    vector<string> order;
    for (size_t i = 0; i < recs.size(); ++i) {
        if (!byChrom.count(recs[i].chrom())) order.push_back(recs[i].chrom());
        byChrom[recs[i].chrom()].push_back(recs[i].len());
    }
    outLine("chrom\tcount\tsum\tmin\tmax\tmean");
    for (size_t i = 0; i < order.size(); ++i) {
        vector<long> &v = byChrom[order[i]];
        long sum = 0, mn = v.empty() ? 0 : v[0], mx = v.empty() ? 0 : v[0];
        for (size_t j = 0; j < v.size(); ++j) {
            sum += v[j];
            if (v[j] < mn) mn = v[j];
            if (v[j] > mx) mx = v[j];
        }
        double mean = v.empty() ? 0.0 : (double)sum / (double)v.size();
        std::ostringstream ss; ss << std::setprecision(6) << mean;
        outLine(order[i] + "\t" + num2str((long)v.size()) + "\t" + num2str(sum) + "\t" +
                num2str(mn) + "\t" + num2str(mx) + "\t" + ss.str());
    }
    OUT.flush();
    return 0;
}
