struct Fasta {
    map<string, string> seqs;
    map<string, string> fullHdrs;
    void load(const string &path) {
        LineReader lr(path);
        if (!lr.ok()) die("Unable to open file " + path + ". Exiting.");
        string line, cur;
        while (lr.next(line)) {
            if (line.size() && line[0] == '>') {
                cur = line.substr(1);
                fullHdrs[cur] = cur;
                size_t p = cur.find_first_of(" \t");
                if (p != string::npos) cur = cur.substr(0, p);
                if (!seqs.count(cur)) seqs[cur] = "";
            } else if (!cur.empty()) {
                string s;
                for (size_t i = 0; i < line.size(); ++i) {
                    char c = line[i];
                    if (c == ' ' || c == '\t' || c == '\r') continue;
                    s += c;
                }
                seqs[cur] += s;
            }
        }
    }
};

static string revComp(const string &s, bool rna) {
    string out;
    for (int i = (int)s.size()-1; i >= 0; --i) {
        char c = s[i];
        switch (toupper_(c)) {
            case 'A': out += rna ? 'U' : 'T'; break;
            case 'T': out += 'A'; break;
            case 'U': out += 'A'; break;
            case 'C': out += 'G'; break;
            case 'G': out += 'C'; break;
            case 'N': out += 'N'; break;
            case 'a': out += rna ? 'u' : 't'; break;
            case 't': out += 'a'; break;
            case 'u': out += 'a'; break;
            case 'c': out += 'g'; break;
            case 'g': out += 'c'; break;
            case 'n': out += 'n'; break;
            default: out += c; break;
        }
    }
    return out;
}

