int cmd_nuc(int argc, char **argv) {
    string fiFile, bedFile, pattern;
    bool s = false, seqOpt = false, ignoreCase = false, fullHeader = false;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("nuc"); }
        else if (arg == "-fi") { if (i+1>=argc) bedFatal("-fi option given, but no file specified."); fiFile = argv[++i]; }
        else if (arg == "-bed") { if (i+1>=argc) bedFatal("-bed option given, but no file specified."); bedFile = argv[++i]; }
        else if (arg == "-s") s = true;
        else if (arg == "-seq") seqOpt = true;
        else if (arg == "-pattern") { if (i+1>=argc) bedFatal("-pattern option given, but no value specified."); pattern = argv[++i]; }
        else if (arg == "-C") ignoreCase = true;
        else if (arg == "-fullHeader") fullHeader = true;
        else { fputs(HELP_nuc, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (fiFile.empty() || bedFile.empty()) { fputs(HELP_nuc, stderr); bedFatal("The following parameters are required: -fi -bed"); }
    Fasta fa;
    fa.load(fiFile);
    vector<BedRec> recs;
    vector<string> hdr;
    loadRecords(bedFile, recs, hdr);
    for (size_t i = 0; i < recs.size(); ++i) {
        const BedRec &r = recs[i];
        map<string,string>::iterator it = fa.seqs.find(r.chrom());
        if (it == fa.seqs.end()) die("Unable to find the chromosome (" + r.chrom() + ") in the fasta file");
        const string &seq = it->second;
        long ss = r.start, ee = r.end;
        if (ss < 0) ss = 0;
        if (ee > (long)seq.size()) ee = (long)seq.size();
        string sub = ee > ss ? seq.substr(ss, ee - ss) : string("");
        if (s && r.hasStrand() && r.strand() == "-") sub = revComp(sub, false);
        long nA = 0, nC = 0, nG = 0, nT = 0, nN = 0, nO = 0;
        for (size_t p = 0; p < sub.size(); ++p) {
            switch (toupper_(sub[p])) {
                case 'A': nA++; break;
                case 'C': nC++; break;
                case 'G': nG++; break;
                case 'T': nT++; break;
                case 'U': nT++; break;
                case 'N': nN++; break;
                default: nO++; break;
            }
        }
        double len = (double)sub.size();
        double pctAT = len > 0 ? 100.0 * (nA + nT) / len : 0.0;
        double pctGC = len > 0 ? 100.0 * (nC + nG) / len : 0.0;
        std::ostringstream ss1, ss2;
        ss1 << std::setprecision(6) << std::fixed << pctAT;
        ss2 << std::setprecision(6) << std::fixed << pctGC;
