                      num2str(nC) + "\t" + num2str(nG) + "\t" + num2str(nT) + "\t" + num2str(nN) + "\t" +
                      num2str(nO) + "\t" + num2str(sub.size());
        if (seqOpt) line += "\t" + sub;
        if (!pattern.empty()) {
            long cnt = 0;
            string pat = pattern, hay = sub;
            if (ignoreCase) { pat = toLower(pat); hay = toLower(hay); }
            if (pat.size() && hay.size() >= pat.size()) {
                for (size_t p = 0; p + pat.size() <= hay.size(); ++p)
                    if (hay.compare(p, pat.size(), pat) == 0) cnt++;
            }
            line += "\t" + num2str(cnt);
        }
        outLine(line);
    }
    OUT.flush();
    return 0;
}
