static string revComp(const string &s, bool rna) {
    string out;
    for (int i = (int)s.size()-1; i >= 0; --i) {
        char c = s[i];
        switch (toupper_(c)) {
            case 'A': out += rna ? 'U' : 'T'; break;
            case 'T': out += 'A'; break;
            case 'U': out += 'A'; break;
            case 'C': out += 'G'; break;
            case 'G': out += 'C'; break;
            case 'N': out += 'N'; break;
            case 'a': out += rna ? 'u' : 't'; break;
            case 't': out += 'a'; break;
            case 'u': out += 'a'; break;
            case 'c': out += 'g'; break;
            case 'g': out += 'c'; break;
            case 'n': out += 'n'; break;
            default: out += c; break;
        }
    }
    return out;
}

