            } else seq[p] = mc;
        }
    }
    // write output
    FILE *fp = fopen(foFile.c_str(), "w");
    if (!fp) die("Unable to open file " + foFile + ". Exiting.");
    for (map<string,string>::iterator it = fa.seqs.begin(); it != fa.seqs.end(); ++it) {
        fprintf(fp, ">%s\n", it->first.c_str());
        const string &s = it->second;
        size_t p = 0;
