void BamFile::read(const string &path) {
    ok = false;
    Bgzf b(path);
    if (!b.g) die("Unable to open file " + path + ". Exiting.");
    // read everything
    string data;
    char buf[65536];
    int n;
    while ((n = gzread(b.g, buf, sizeof(buf))) > 0) data.append(buf, n);
    if (data.size() < 12 || memcmp(data.data(), "BAM\x01", 4) != 0) {
        die("Unable to open file " + path + ". Exiting.");
    }
    size_t p = 4;
    long l_text = le32(data, p);
    text = data.substr(p, l_text); p += l_text;
    long n_ref = le32(data, p); p += 4;
    for (long i = 0; i < n_ref; ++i) {
        long l_name = le32(data, p); p += 4;
        string nm = data.substr(p, l_name - 1); p += l_name;
        long l_ref = le32(data, p); p += 4;
        refs.push_back(nm);
        refLens.push_back(l_ref);
    }
    while (p + 4 <= data.size()) {
        long bs = le32(data, p); p += 4;
        if (bs == 0 || p + (size_t)bs > data.size()) break;
        size_t end = p + bs;
        size_t q = p;
        if (q + 32 > end) { p = end; continue; }
        int refID = le32(data, q); q += 4;
        long pos = le32(data, q); q += 4;
        unsigned l_rname = (unsigned char)data[q]; q += 1;
        unsigned mapq = (unsigned char)data[q]; q += 1;
        unsigned bin = le16(data, q); q += 2;
        unsigned n_cig = le16(data, q); q += 2;
        unsigned flag = le16(data, q); q += 2;
        long l_seq = le32(data, q); q += 4;
        long next_ref = le32(data, q); q += 4;
        long next_pos = le32(data, q); q += 4;
        long l_tag = le32(data, q); q += 4;
        BamRec r;
        r.refID = refID; r.pos = pos; r.mapq = mapq; r.flag = flag; r.nCigar = n_cig;
        r.name = data.substr(q, l_rname - 1); q += l_rname;
        for (unsigned c = 0; c < n_cig && q + 4 <= end; ++c) {
            r.cigar.push_back(le32(data, q)); q += 4;
        }
        // sequence
        static const char CODE2BASE[16] = {'=','A','C','M','G','R','S','V','T','W','Y','N','K','D','B','H'};
        long half = (l_seq + 1) / 2;
        for (long c = 0; c < l_seq && q < end; ) {
            unsigned char byte = (unsigned char)data[q]; q += 1;
            for (int k = 0; k < 2 && c < l_seq; ++k, ++c) {
                unsigned v = (k == 0) ? (byte >> 4) : (byte & 0xf);
                r.seq += CODE2BASE[v];
            }
        }
        // quality
        for (long c = 0; c < l_seq && q < end; ++c) { r.qual += (char)(33 + (unsigned char)data[q]); q += 1; }
        // tags
        if (l_tag > 0 && q + (size_t)l_tag <= end) {
            string t = data.substr(q, l_tag);
            // parse auxiliary tags: "XX:type:value"
            size_t tp = 0;
            while (tp < t.size()) {
                size_t e = t.find('\0', tp);
                if (e == string::npos) break;
                r.tags.push_back(t.substr(tp, e - tp));
                tp = e + 1;
            }
        }
        recs.push_back(r);
        p = end;
    }
    ok = true;
}
