struct Bgzf {
    gzFile g;
    Bgzf(const string &path) {
        g = gzopen(path.c_str(), "rb");
    }
    ~Bgzf() { if (g) gzclose(g); }
};

void BamFile::read(const string &path) {
    ok = false;
    Bgzf b(path);
    if (!b.g) die("Unable to open file " + path + ". Exiting.");
    // read everything
    string data;
    char buf[65536];
    int n;
