// tools_bam.cpp - bamtobed, bamtofastq, bedtobam, bedpetobam, multicov, tag
#include "tools.h"
#include "numops.h"
#include "helpstrings.h"
#include "bam.h"

static string cigarStr(const vector<unsigned> &c) {
    static const char OPS[] = "MIDNSHP=X";
    string s;
    for (size_t i = 0; i < c.size(); ++i) {
        unsigned op = c[i] & 0xf, len = c[i] >> 4;
        s += num2str((long)len);
        s += (op < 9) ? string(1, OPS[op]) : string("?");
    }
    return s;
}

int cmd_bamtobed(int argc, char **argv) {
    string inFile;
    bool bedpe = false, bed12 = false, split = false, splitD = false, ed = false, cigar = false;
    string tag, color = "255,0,0";
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("bamtobed"); }
        else if (arg == "-i") { if (i+1>=argc) bedFatal("-i option given, but no file specified."); inFile = argv[++i]; }
        else if (arg == "-bedpe") bedpe = true;
        else if (arg == "-mate1") {}
        else if (arg == "-bed12") { bed12 = true; split = true; }
        else if (arg == "-split") split = true;
        else if (arg == "-splitD") { split = true; splitD = true; }
        else if (arg == "-ed") ed = true;
        else if (arg == "-tag") { if (i+1<argc) tag = argv[++i]; }
        else if (arg == "-color") { if (i+1<argc) color = argv[++i]; }
        else if (arg == "-cigar") cigar = true;
        else { fputs(HELP_bamtobed, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (inFile.empty()) { fputs(HELP_bamtobed, stderr); bedFatal("The following parameters are required: -i"); }
    BamFile bf;
    bf.read(inFile);
    for (size_t i = 0; i < bf.recs.size(); ++i) {
        const BamRec &r = bf.recs[i];
        if (r.refID < 0 || (size_t)r.refID >= bf.refs.size()) continue;
        string chrom = bf.refs[r.refID];
        long score = r.mapq;
        if (ed) {
            for (size_t t = 0; t < r.tags.size(); ++t) {
                if (r.tags[t].compare(0, 3, "NM:") == 0) score = atol(r.tags[t].c_str() + 3);
            }
        } else if (!tag.empty()) {
            score = 0;
            for (size_t t = 0; t < r.tags.size(); ++t) {
                if (r.tags[t].compare(0, tag.size()+1, tag + ":") == 0) score = atol(r.tags[t].c_str() + tag.size()+1);
            }
        }
        if (!split || r.cigar.empty()) {
            string line = chrom + "\t" + num2str(r.pos) + "\t" + num2str(r.end()) + "\t" + r.name +
                          "\t" + num2str(score) + "\t" + (r.reverse() ? "-" : "+");
            if (cigar) line += "\t" + cigarStr(r.cigar);
            outLine(line);
        } else {
            // split into blocks on N (op 3) and optionally D (op 2)
            long p = r.pos;
            long bs = r.pos;
            for (size_t c = 0; c < r.cigar.size(); ++c) {
                unsigned op = r.cigar[c] & 0xf, len = r.cigar[c] >> 4;
                if (op == 3 || (splitD && op == 2)) {
                    if (p > bs) {
                        outLine(chrom + "\t" + num2str(bs) + "\t" + num2str(p) + "\t" + r.name +
                                "\t" + num2str(score) + "\t" + (r.reverse() ? "-" : "+"));
                    }
                    bs = p + (op == 3 ? len : 0);
                    p += len;
                } else p += len;
            }
            if (p > bs)
                outLine(chrom + "\t" + num2str(bs) + "\t" + num2str(p) + "\t" + r.name +
                        "\t" + num2str(score) + "\t" + (r.reverse() ? "-" : "+"));
        }
    }
    OUT.flush();
    return 0;
}

int cmd_bamtofastq(int argc, char **argv) {
    string inFile, fq, fq2;
    bool tags = false;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("bamtofastq"); }
        else if (arg == "-i") { if (i+1>=argc) bedFatal("-i option given, but no file specified."); inFile = argv[++i]; }
        else if (arg == "-fq") { if (i+1>=argc) bedFatal("-fq option given, but no file specified."); fq = argv[++i]; }
        else if (arg == "-fq2") { if (i+1>=argc) bedFatal("-fq2 option given, but no file specified."); fq2 = argv[++i]; }
        else if (arg == "-tags") tags = true;
        else { fputs(HELP_bamtofastq, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (inFile.empty() || fq.empty()) { fputs(HELP_bamtofastq, stderr); bedFatal("The following parameters are required: -i -fq"); }
    BamFile bf;
    bf.read(inFile);
    FILE *f1 = strcmp(fq.c_str(), "/dev/stdout") == 0 ? stdout : fopen(fq.c_str(), "w");
    if (!f1) die("Unable to open file " + fq + ". Exiting.");
    FILE *f2 = fq2.empty() ? NULL : (strcmp(fq2.c_str(), "/dev/stdout") == 0 ? stdout : fopen(fq2.c_str(), "w"));
    if (fq2.size() && !f2) die("Unable to open file " + fq2 + ". Exiting.");
    for (size_t i = 0; i < bf.recs.size(); ++i) {
        const BamRec &r = bf.recs[i];
        FILE *fp = (f2 && r.reverse()) ? f2 : f1;
        fprintf(fp, "@%s\n%s\n+\n%s\n", r.name.c_str(), r.seq.c_str(), r.qual.c_str());
    }
    if (f1 != stdout) fclose(f1);
    if (f2 && f2 != stdout) fclose(f2);
    return 0;
}

static void loadGenomeForBam(const string &gFile, vector<string> &refs, vector<long> &lens) {
    GENOME.load(gFile);
    refs = GENOME.chroms;
    for (size_t i = 0; i < refs.size(); ++i) lens.push_back(GENOME.size(refs[i]));
}

int cmd_bedtobam(int argc, char **argv) {
    string inFile, gFile;
    int mapq = 255;
    bool bed12 = false, ubam = false;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("bedtobam"); }
        else if (arg == "-i") { if (i+1>=argc) bedFatal("-i option given, but no file specified."); inFile = argv[++i]; }
        else if (arg == "-g") { if (i+1>=argc) bedFatal("-g option given, but no genome file specified."); gFile = argv[++i]; }
        else if (arg == "-mapq") { if (i+1<argc) mapq = atoi(argv[++i]); }
        else if (arg == "-bed12") bed12 = true;
        else if (arg == "-ubam") ubam = true;
        else { fputs(HELP_bedtobam, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (inFile.empty() || gFile.empty()) { fputs(HELP_bedtobam, stderr); bedFatal("The following parameters are required: -i -g"); }
    vector<string> refs; vector<long> lens;
    loadGenomeForBam(gFile, refs, lens);
    vector<BedRec> recs;
    vector<string> hdr;
    loadRecords(inFile, recs, hdr);
    vector<BamRec> brecs;
    for (size_t i = 0; i < recs.size(); ++i) {
        const BedRec &r = recs[i];
        int refID = -1;
        for (size_t j = 0; j < refs.size(); ++j) if (refs[j] == r.chrom()) { refID = (int)j; break; }
        BamRec b;
        b.refID = refID; b.pos = r.start; b.mapq = mapq; b.flag = 0;
        b.name = r.fields.size() > 3 ? r.fields[3] : string("*");
        if (r.hasStrand() && r.strand() == "-") b.flag |= 0x10;
        long len = r.end - r.start;
        if (bed12 && r.fields.size() >= 12) {
            long nb = atol(r.fields[9].c_str());
            vector<string> bs, be;
            splitList(r.fields[10], bs);
            splitList(r.fields[11], be);
            b.cigar.push_back((0 << 4) | 4);   // pad to start? simplified
            for (long q = 0; q < nb && q < (long)bs.size(); ++q) {
                long s = atol(bs[q].c_str()), e = atol(be[q].c_str());
                if (q > 0) b.cigar.push_back(((s - (q ? atol(be[q-1].c_str()) : 0)) << 4) | 3);
                b.cigar.push_back(((e - s) << 4) | 0);
            }
            b.cigar.push_back(((r.end - r.start - (long)be.back().size()) << 4) | 4);
        } else {
            if (len > 0) b.cigar.push_back(((unsigned)len << 4) | 0);
        }
        brecs.push_back(b);
    }
    writeBam("-", refs, lens, brecs, ubam);
    return 0;
}

