static string cigarStr(const vector<unsigned> &c) {
    static const char OPS[] = "MIDNSHP=X";
    string s;
    for (size_t i = 0; i < c.size(); ++i) {
        unsigned op = c[i] & 0xf, len = c[i] >> 4;
        s += num2str((long)len);
