}

int cmd_bamtobed(int argc, char **argv) {
    string inFile;
    bool bedpe = false, bed12 = false, split = false, splitD = false, ed = false, cigar = false;
    string tag, color = "255,0,0";
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("bamtobed"); }
        else if (arg == "-i") { if (i+1>=argc) bedFatal("-i option given, but no file specified."); inFile = argv[++i]; }
        else if (arg == "-bedpe") bedpe = true;
        else if (arg == "-mate1") {}
        else if (arg == "-bed12") { bed12 = true; split = true; }
