        else if (arg == "-splitD") { split = true; splitD = true; }
        else if (arg == "-ed") ed = true;
        else if (arg == "-tag") { if (i+1<argc) tag = argv[++i]; }
        else if (arg == "-color") { if (i+1<argc) color = argv[++i]; }
        else if (arg == "-cigar") cigar = true;
