        const BamRec &r = bf.recs[i];
        if (r.refID < 0 || (size_t)r.refID >= bf.refs.size()) continue;
        string chrom = bf.refs[r.refID];
        long score = r.mapq;
        if (ed) {
            for (size_t t = 0; t < r.tags.size(); ++t) {
                if (r.tags[t].compare(0, 3, "NM:") == 0) score = atol(r.tags[t].c_str() + 3);
            }
        } else if (!tag.empty()) {
            score = 0;
            for (size_t t = 0; t < r.tags.size(); ++t) {
                if (r.tags[t].compare(0, tag.size()+1, tag + ":") == 0) score = atol(r.tags[t].c_str() + tag.size()+1);
            }
        }
        if (!split || r.cigar.empty()) {
            string line = chrom + "\t" + num2str(r.pos) + "\t" + num2str(r.end()) + "\t" + r.name +
