        else if (arg == "-fq") { if (i+1>=argc) bedFatal("-fq option given, but no file specified."); fq = argv[++i]; }
        else if (arg == "-fq2") { if (i+1>=argc) bedFatal("-fq2 option given, but no file specified."); fq2 = argv[++i]; }
        else if (arg == "-tags") tags = true;
        else { fputs(HELP_bamtofastq, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (inFile.empty() || fq.empty()) { fputs(HELP_bamtofastq, stderr); bedFatal("The following parameters are required: -i -fq"); }
    BamFile bf;
