    FILE *f2 = fq2.empty() ? NULL : (strcmp(fq2.c_str(), "/dev/stdout") == 0 ? stdout : fopen(fq2.c_str(), "w"));
    if (fq2.size() && !f2) die("Unable to open file " + fq2 + ". Exiting.");
    for (size_t i = 0; i < bf.recs.size(); ++i) {
