            b.cigar.push_back((0 << 4) | 4);   // pad to start? simplified
            for (long q = 0; q < nb && q < (long)bs.size(); ++q) {
                long s = atol(bs[q].c_str()), e = atol(be[q].c_str());
                if (q > 0) b.cigar.push_back(((s - (q ? atol(be[q-1].c_str()) : 0)) << 4) | 3);
                b.cigar.push_back(((e - s) << 4) | 0);
            }
            b.cigar.push_back(((r.end - r.start - (long)be.back().size()) << 4) | 4);
        } else {
            if (len > 0) b.cigar.push_back(((unsigned)len << 4) | 0);
        }
        brecs.push_back(b);
    }
    writeBam("-", refs, lens, brecs, ubam);
    return 0;
}

int cmd_bedpetobam(int argc, char **argv) {
    string inFile, gFile;
    int mapq = 255;
    bool ubam = false;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("bedpetobam"); }
        else if (arg == "-i") { if (i+1>=argc) bedFatal("-i option given, but no file specified."); inFile = argv[++i]; }
        else if (arg == "-g") { if (i+1>=argc) bedFatal("-g option given, but no genome file specified."); gFile = argv[++i]; }
        else if (arg == "-mapq") { if (i+1<argc) mapq = atoi(argv[++i]); }
        else if (arg == "-ubam") ubam = true;
        else { fputs(HELP_bedpetobam, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (inFile.empty() || gFile.empty()) { fputs(HELP_bedpetobam, stderr); bedFatal("The following parameters are required: -i -g"); }
    vector<string> refs; vector<long> lens;
    loadGenomeForBam(gFile, refs, lens);
    vector<BedRec> recs;
    vector<string> hdr;
    loadRecords(inFile, recs, hdr);
    vector<BamRec> brecs;
    for (size_t i = 0; i < recs.size(); ++i) {
        const BedRec &r = recs[i];
        if (r.fields.size() < 12) continue;
        long s1 = atol(r.fields[1].c_str()), e1 = atol(r.fields[2].c_str());
        long s2 = atol(r.fields[6].c_str()), e2 = atol(r.fields[7].c_str());
        int ref1 = -1, ref2 = -1;
        for (size_t j = 0; j < refs.size(); ++j) {
            if (refs[j] == r.chrom()) ref1 = (int)j;
            if (refs[j] == r.fields[5]) ref2 = (int)j;
        }
        BamRec b;
        b.refID = ref1; b.pos = s1; b.mapq = mapq;
        b.flag = 0x1 | 0x40;
        b.name = r.fields.size() > 3 ? r.fields[3] : string("*");
        b.cigar.push_back(((e1 - s1) << 4) | 0);
        brecs.push_back(b);
        BamRec b2 = b;
        b2.refID = ref2; b2.pos = s2;
        b2.flag = 0x1 | 0x80 | 0x20;
        b2.cigar.clear();
        b2.cigar.push_back(((e2 - s2) << 4) | 0);
        brecs.push_back(b2);
    }
    writeBam("-", refs, lens, brecs, ubam);
    return 0;
}

int cmd_multicov(int argc, char **argv) {
    BinOpts o;
    vector<string> bams;
    string bedFile;
    long minq = 0;
    bool D = false, F = false, p = false;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("multicov"); }
        else if (arg == "-bams") { ++i; while (i < argc && argv[i][0] != '-') bams.push_back(argv[i++]); --i; }
        else if (arg == "-bed") { if (i+1>=argc) bedFatal("-bed option given, but no file specified."); bedFile = argv[++i]; }
        else if (arg == "-q") { if (i+1<argc) minq = atol(argv[++i]); }
        else if (arg == "-D") D = true;
        else if (arg == "-F") F = true;
        else if (arg == "-p") p = true;
        else if (parseCommonOpt(arg, argc, argv, i, o)) {}
        else { fputs(HELP_multicov, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (bams.empty() || bedFile.empty()) { fputs(HELP_multicov, stderr); bedFatal("The following parameters are required: -bams -bed"); }
    vector<BedRec> arecs;
    vector<string> hdr;
    loadRecords(bedFile, arecs, hdr);
    vector<BamFile> bfs(bams.size());
    for (size_t b = 0; b < bams.size(); ++b) bfs[b].read(bams[b]);
    for (size_t ai = 0; ai < arecs.size(); ++ai) {
        const BedRec &a = arecs[ai];
        string line = a.raw();
        for (size_t b = 0; b < bams.size(); ++b) {
            long cnt = 0;
            const vector<BamRec> &recs = bfs[b].recs;
            for (size_t j = 0; j < recs.size(); ++j) {
                const BamRec &r = recs[j];
                if (r.refID < 0 || (size_t)r.refID >= bfs[b].refs.size()) continue;
                if (bfs[b].refs[r.refID] != a.chrom()) continue;
                if (r.mapq < minq) continue;
                if (!D && r.duplicate()) continue;
                if (!F && r.qcFail()) continue;
                if (p && !r.properPair()) continue;
                long e = r.end();
                if (e > a.start && r.pos < a.end) cnt++;
            }
            line += "\t" + num2str(cnt);
        }
        outLine(line);
    }
    OUT.flush();
    return 0;
}

int cmd_tag(int argc, char **argv) {
    BinOpts o;
    string inFile;
    vector<string> files, labels;
    string tagStr = "YB";
    bool names = false, scores = false, intervals = false;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("tag"); }
        else if (arg == "-i") { if (i+1>=argc) bedFatal("-i option given, but no file specified."); inFile = argv[++i]; }
        else if (arg == "-files") { ++i; while (i < argc && argv[i][0] != '-') files.push_back(argv[i++]); --i; }
        else if (arg == "-labels") { ++i; while (i < argc && argv[i][0] != '-') labels.push_back(argv[i++]); --i; }
        else if (arg == "-tag") { if (i+1<argc) tagStr = argv[++i]; }
        else if (arg == "-names") names = true;
        else if (arg == "-scores") scores = true;
        else if (arg == "-intervals") intervals = true;
        else if (parseCommonOpt(arg, argc, argv, i, o)) {}
        else { fputs(HELP_tag, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (inFile.empty() || files.empty()) { fputs(HELP_tag, stderr); bedFatal("The following parameters are required: -i -files -labels"); }
    vector<FileBins> bsets;
    vector<vector<BedRec> > recsets;
    loadFiles(files, bsets, recsets);
    BamFile bf;
    bf.read(inFile);
    vector<BamRec> out;
    for (size_t i = 0; i < bf.recs.size(); ++i) {
        BamRec r = bf.recs[i];
        for (size_t f = 0; f < bsets.size(); ++f) {
            const ChromBins *cb = bsets[f].get(bf.refs[r.refID]);
            bool hit = false;
            if (cb) {
                cb->query(r.pos, r.end(), tmp);
                for (size_t j = 0; j < tmp.size(); ++j) {
                    const BedRec &b = cb->recs[tmp[j]];
                    if (b.end > r.pos && b.start < r.end()) { hit = true; break; }
                }
            }
            string val;
            if (intervals) val = hit ? (labels.size() > f ? labels[f] : num2str(f+1)) : string(".");
            else if (names) {
                val = "0";
                if (hit && cb) {
                    cb->query(r.pos, r.end(), tmp);
                    for (size_t j = 0; j < tmp.size(); ++j) {
                        const BedRec &b = cb->recs[tmp[j]];
                        if (b.end > r.pos && b.start < r.end()) { val = b.fields.size() > 3 ? b.fields[3] : string(""); break; }
                    }
                }
            } else if (scores) {
                val = "0";
                if (hit && cb) {
                    cb->query(r.pos, r.end(), tmp);
                    for (size_t j = 0; j < tmp.size(); ++j) {
                        const BedRec &b = cb->recs[tmp[j]];
                        if (b.end > r.pos && b.start < r.end()) { val = b.fields.size() > 4 ? b.fields[4] : string("0"); break; }
                    }
                }
            } else val = hit ? "1" : "0";
            r.tags.push_back(tagStr + ":i:" + val);
        }
        out.push_back(r);
    }
    writeBam("-", bf.refs, bf.refLens, out, false);
    return 0;
}
