// write a BAM file
void writeBam(const string &path, const vector<string> &refs, const vector<long> &refLens,
              const vector<BamRec> &recs, bool uncompressed) {
    string hdr;
    hdr.append("BAM\x01", 4);
    string text;
    for (size_t i = 0; i < refs.size(); ++i) {
        char buf[256];
        snprintf(buf, sizeof(buf), "@SQ\tSN:%s\tLN:%ld\n", refs[i].c_str(), refLens[i]);
        text += buf;
    }
    put32(hdr, (unsigned)text.size());
    hdr += text;
    put32(hdr, (unsigned)refs.size());
    for (size_t i = 0; i < refs.size(); ++i) {
        put32(hdr, (unsigned)(refs[i].size() + 1));
        hdr += refs[i];
        hdr += '\0';
        put32(hdr, (unsigned)refLens[i]);
    }
    string body;
    for (size_t i = 0; i < recs.size(); ++i) {
        const BamRec &r = recs[i];
        string rec;
        put32(rec, (unsigned)r.refID);
        put32(rec, (unsigned)r.pos);
        rec += (char)(r.name.size() + 1);
        rec += (char)r.mapq;
        long len = 0;
        for (size_t c = 0; c < r.cigar.size(); ++c) len += (long)(r.cigar[c] >> 4);
        unsigned bin = 0;
        if (len > 0) {
            long s = r.pos, e = r.end() - 1;
            // compute the UCSC bin
            if (e < 16384) bin = 5849 + (unsigned)(s >> 14);
            else if (e < 131072) bin = 585 + (unsigned)(s >> 17);
            else if (e < 1048576) bin = 73 + (unsigned)(s >> 20);
            else if (e < 8388608) bin = 9 + (unsigned)(s >> 23);
            else if (e < 67108864) bin = 1 + (unsigned)(s >> 26);
            else bin = 0;
        }
        put16(rec, bin);
        put16(rec, (unsigned)r.cigar.size());
        put16(rec, r.flag);
        put32(rec, (unsigned)r.seq.size());
        put32(rec, 0xffffffffu);
        put32(rec, 0xffffffffu);
        put32(rec, 0);
        rec += r.name; rec += '\0';
        for (size_t c = 0; c < r.cigar.size(); ++c) put32(rec, r.cigar[c]);
        // seq packed
        for (size_t p = 0; p < r.seq.size(); p += 2) {
            unsigned hi = 15, lo = 15;
            static const char BASE2CODE[256] = {0};
            (void)BASE2CODE;
            unsigned a = 15, b2 = 15;
            if (p < r.seq.size()) { char ch = toupper_(r.seq[p]); a = (ch=='A')?1:(ch=='C')?2:(ch=='G')?4:(ch=='T')?8:(ch=='U')?8:15; }
            if (p+1 < r.seq.size()) { char ch = toupper_(r.seq[p+1]); b2 = (ch=='A')?1:(ch=='C')?2:(ch=='G')?4:(ch=='T')?8:(ch=='U')?8:15; }
            hi = a; lo = b2;
            rec += (char)((hi << 4) | lo);
        }
        for (size_t p = 0; p < r.qual.size(); ++p) rec += (char)((unsigned char)r.qual[p] - 33);
        for (size_t t = 0; t < r.tags.size(); ++t) {
            string tag = r.tags[t] + "\x01i\x02";
            tag += (char)1;  // int8 type
            tag += (char)atoi(r.tags[t].substr(r.tags[t].rfind(':')+1).c_str());
            (void)tag;
        }
        put32((string&)body, 0);
        body.erase(body.size()-4, 4);
        put32(body, (unsigned)rec.size());
        body += rec;
    }
    string out;
    if (uncompressed) {
        out = hdr + body;
    } else {
        // BGZF blocks; split the data into <= 64k blocks
        string data = hdr + body;
        size_t p = 0;
        while (p < data.size()) {
            size_t n = data.size() - p;
            if (n > 60000) n = 60000;
            uLongf clen = compressBound(n);
            vector<unsigned char> cb(clen);
            z_stream_s *zs = NULL;
            (void)zs;
            compress2(&cb[0], &clen, (const Bytef*)data.data() + p, n, 6);
            // build a gzip member
            string gm;
            gm += (char)0x1f; gm += (char)0x8b; gm += (char)0x08; gm += (char)0x04;
            gm += (char)0; gm += (char)0; gm += (char)0; gm += (char)0; gm += (char)0; gm += (char)0xff;
            put16(gm, 6);
            gm += 'B'; gm += 'C';
            put16(gm, (unsigned)(clen + 25));
            gm.append((const char*)&cb[0], clen);
            put32(gm, (unsigned)crc32(0L, (const Bytef*)data.data() + p, n));
            put32(gm, (unsigned)n);
            out += gm;
            p += n;
        }
        // EOF marker
        const char eof[28] = {(char)0x1f,(char)0x8b,(char)0x08,(char)0x04,(char)0,(char)0,(char)0,(char)0,(char)0,(char)0xff,
                              (char)0x06,(char)0x00,(char)0x42,(char)0x43,(char)0x02,(char)0x00,(char)0x1b,(char)0x00,
                              (char)0x03,(char)0x00,(char)0,(char)0,(char)0,(char)0,(char)0,(char)0,(char)0,(char)0};
        out.append(eof, 28);
    }
    FILE *fp = path == "-" ? stdout : fopen(path.c_str(), "wb");
    if (!fp) die("Unable to open file " + path + ". Exiting.");
    fwrite(out.data(), 1, out.size(), fp);
    if (fp != stdout) fclose(fp);
}
