// tools_pair.cpp - fisher, reldist, pairtobed, pairtopair
#include "tools.h"
#include "numops.h"
#include "helpstrings.h"
#include "bam.h"
#include <cmath>

struct Hit {
    int file;
    int idx;
    const BedRec *rec;
};
static vector<int> tmp;
static void collect(const vector<FileBins> &bsets, const string &chrom, long qs, long qe,
                    vector<Hit> &hits) {
    hits.clear();
    for (size_t f = 0; f < bsets.size(); ++f) {
        const ChromBins *cb = bsets[f].get(chrom);
        if (!cb) continue;
        cb->query(qs, qe, tmp);
        for (size_t j = 0; j < tmp.size(); ++j) {
            Hit h; h.file = (int)f; h.idx = tmp[j]; h.rec = &cb->recs[tmp[j]];
            hits.push_back(h);
        }
    }
}
static void loadFiles(const vector<string> &paths, vector<FileBins> &out,
                      vector<vector<BedRec> > &recsets) {
    out.clear(); recsets.clear();
    for (size_t i = 0; i < paths.size(); ++i) {
        vector<BedRec> recs;
        vector<string> hdr;
        loadRecords(paths[i], recs, hdr);
        FileBins fb; fb.build(recs);
        out.push_back(fb);
        recsets.push_back(recs);
    }
}

// ---------- fisher ----------
// Fisher's exact test for a 2x2 table
static double fisherP(double a, double b, double c, double d, int tail) {
    // tail: 0 = two-tail, 1 = left, 2 = right
    double n = a + b + c + d;
    if (n <= 0) return 1.0;
    double r1 = a + b, c1 = a + c;
    // hypergeometric probability of the observed table
    double lg = lgamma(n+1) - lgamma(a+1) - lgamma(b+1) - lgamma(c+1) - lgamma(d+1)
                + lgamma(r1+1) + lgamma(n-r1+1) + lgamma(c1+1) + lgamma(n-c1+1) - lgamma(n+1);
    double pobs = exp(lg);
    double sum = 0;
    double lo = c1 - (n - r1) > 0 ? c1 - (n - r1) : 0;
    double hi = c1 < r1 ? c1 : r1;
    for (double x = lo; x <= hi; x += 1) {
        double dd = c1 - x;
        if (dd < 0 || (r1 - x) < 0) continue;
        double l = lgamma(n+1) - lgamma(x+1) - lgamma(r1-x+1) - lgamma(dd+1) - lgamma(n-r1-dd+1);
        double p = exp(l);
        if (tail == 0) {
            if (p <= pobs * (1 + 1e-7)) sum += p;
        } else if (tail == 1) {
            if (x <= a) sum += p;
        } else {
            if (x >= a) sum += p;
        }
    }
    if (sum > 1.0) sum = 1.0;
    return sum;
}

