        else if (arg == "-a") { if (i+1 >= argc) bedFatal("No input file given. Exiting."); aFile = argv[++i]; }
        else if (arg == "-b") { if (i+1 >= argc) bedFatal("-b option given, but no database file specified."); bFile = argv[++i]; }
        else if (arg == "-g") { if (i+1 >= argc) bedFatal("-g option given, but no genome file specified."); gFile = argv[++i]; }
