    for (size_t i = 0; i < GENOME.chroms.size(); ++i) genomeSize += GENOME.size(GENOME.chroms[i]);
    long aLen = basesA, bLen = basesB;
    // contingency: covered by both / only A / only B / neither
    double a = inter;
    double b = aLen - inter;
    double c = bLen - inter;
    double d = (double)genomeSize - (double)aLen - (double)bLen + (double)inter;
    if (d < 0) d = 0;
    double stat = (a > 0 && d > 0) ? (a*d) / (b > 0 && c > 0 ? (b*c) : 1.0) : 0.0;
    double p = fisherP(a, b, c, d, 0);
    double pl = fisherP(a, b, c, d, 1);
    double pr = fisherP(a, b, c, d, 2);
    auto f6 = [](double v) { std::ostringstream ss; ss << std::setprecision(6) << v; return ss.str(); };
    outLine("fisher statistic:  " + f6(stat));
    outLine("fisher p-value:    " + f6(p));
    outLine("fisher left p:     " + f6(pl));
    outLine("fisher right p:    " + f6(pr));
    outLine("fisher two-tail p: " + f6(p));
    OUT.flush();
    return 0;
}

// ---------- reldist ----------
int cmd_reldist(int argc, char **argv) {
    BinOpts o;
    string aFile, bFile;
    bool detail = false;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("reldist"); }
        else if (arg == "-a") { if (i+1 >= argc) bedFatal("No input file given. Exiting."); aFile = argv[++i]; }
        else if (arg == "-b") { if (i+1 >= argc) bedFatal("-b option given, but no database file specified."); bFile = argv[++i]; }
        else if (arg == "-detail") detail = true;
        else if (parseCommonOpt(arg, argc, argv, i, o)) {}
        else { fputs(HELP_reldist, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (aFile.empty() || bFile.empty()) {
        fputs(HELP_reldist, stderr); bedFatal("The following parameters are required: -a -b");
    }
    vector<FileBins> bsets;
    vector<vector<BedRec> > recsets;
    vector<string> bp(1, bFile);
    loadFiles(bp, bsets, recsets);
    vector<BedRec> arecs;
    vector<string> aheader;
    loadRecords(aFile, arecs, aheader);
    if (o.sorted) {
        checkSorted(arecs, aFile, o);
        checkSorted(recsets[0], bFile, o);
    }
    vector<double> rels;
    long total = 0, overlaps = 0;
    vector<Hit> hits;
    for (size_t ai = 0; ai < arecs.size(); ++ai) {
        const BedRec &a = arecs[ai];
        total++;
        collect(bsets, a.chrom(), a.start, a.end, hits);
        bool any = false;
        double best = -1;
        long len = a.len();
        if (len <= 0) len = 1;
        for (size_t j = 0; j < hits.size(); ++j) {
            const BedRec &b = *hits[j].rec;
            long ov = overlapBases(a, b);
            if (ov > 0) { any = true; best = 0; }
            else {
                long dist = b.end <= a.start ? a.start - b.end : b.start - a.end;
                double rd = (double)dist / (double)len;
                if (best < 0 || rd < best) best = rd;
            }
        }
        if (any) overlaps++;
        double rd = best < 0 ? 1.0 : best;
        rels.push_back(rd);
        if (detail) {
            std::ostringstream ss; ss << std::setprecision(6) << rd;
            outLine(a.raw() + "\t" + ss.str());
        }
    }
    if (!detail) {
        double sum = 0;
        for (size_t i = 0; i < rels.size(); ++i) sum += rels[i];
        double mean = rels.empty() ? 0.0 : sum / (double)rels.size();
        vector<double> sorted = rels;
        std::sort(sorted.begin(), sorted.end());
        double median = sorted.empty() ? 0.0 : (sorted.size() % 2 ? sorted[sorted.size()/2] :
                        (sorted[sorted.size()/2-1] + sorted[sorted.size()/2]) / 2.0);
        double var = 0;
        for (size_t i = 0; i < rels.size(); ++i) var += (rels[i]-mean)*(rels[i]-mean);
        double sd = rels.size() > 1 ? sqrt(var / (double)(rels.size()-1)) : 0.0;
        double skew = sd > 0 ? 0.0 : 0.0;
        auto f6 = [](double v) { std::ostringstream ss; ss << std::setprecision(6) << v; return ss.str(); };
        outLine(num2str(total) + "\t" + num2str(overlaps) + "\t" + num2str(total - overlaps) + "\t" +
                f6(mean) + "\t" + f6(median) + "\t" + f6(skew));
    }
    OUT.flush();
    return 0;
}

