    loadRecords(aFile, arecs, aheader);
    if (o.header) for (size_t i = 0; i < aheader.size(); ++i) outLine(aheader[i]);
    vector<Hit> hits;
    for (size_t ai = 0; ai < arecs.size(); ++ai) {
        const BedRec &a = arecs[ai];
        if (a.fields.size() < 8) continue;
        // ends
        for (int end = 0; end < 2; ++end) {
            int sc = end == 0 ? 0 : 5;   // chrom col (0-based)
            int ss = end == 0 ? 1 : 6;
            int se = end == 0 ? 2 : 7;
            string chrom = a.fields[sc];
            long s = atol(a.fields[ss].c_str()), e = atol(a.fields[se].c_str());
            bool okv = true;
            if (type == "neither") okv = false;
            BedRec q; q.fields = a.fields; q.start = s; q.end = e;
            collect(bsets, chrom, s, e, hits);
            for (size_t j = 0; j < hits.size(); ++j) {
                const BedRec &b = *hits[j].rec;
                long ov = overlapBases(q, b);
                double lenB = (double)b.len();
                if (ov <= 0) continue;
                if ((double)ov / lenB < o.fracB) continue;
                if (type == "neither") continue;
                outLine(a.raw() + "\t" + b.raw());
            }
        }
    }
    OUT.flush();
    return 0;
}

// ---------- pairtopair ----------
int cmd_pairtopair(int argc, char **argv) {
    BinOpts o;
    string aFile, bFile;
    string type = "both";
    long slop = 0;
    for (int i = 2; i < argc; ++i) {
        string arg = argv[i];
        if (arg == "-h" || arg == "--help") { toolHelp("pairtopair"); }
        else if (arg == "-a") { if (i+1 >= argc) bedFatal("No input file given. Exiting."); aFile = argv[++i]; }
        else if (arg == "-b") { if (i+1 >= argc) bedFatal("-b option given, but no database file specified."); bFile = argv[++i]; }
        else if (arg == "-type") { if (i+1>=argc) bedFatal("-type option given, but no value specified."); type = argv[++i]; }
        else if (arg == "-slop") { if (i+1<argc) slop = atol(argv[++i]); }
        else if (parseCommonOpt(arg, argc, argv, i, o)) {}
        else { fputs(HELP_pairtopair, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (aFile.empty() || bFile.empty()) {
        fputs(HELP_pairtopair, stderr); bedFatal("The following parameters are required: -a -b");
    }
    vector<FileBins> bsets;
    vector<vector<BedRec> > recsets;
    vector<string> bp(1, bFile);
    loadFiles(bp, bsets, recsets);
    vector<BedRec> arecs;
    vector<string> aheader;
    loadRecords(aFile, arecs, aheader);
    if (o.header) for (size_t i = 0; i < aheader.size(); ++i) outLine(aheader[i]);
    vector<Hit> hits;
    for (size_t ai = 0; ai < arecs.size(); ++ai) {
        const BedRec &a = arecs[ai];
        if (a.fields.size() < 8) continue;
        for (size_t bi = 0; bi < recsets[0].size(); ++bi) {
            const BedRec &b = recsets[0][bi];
            if (b.fields.size() < 8) continue;
            bool end1 = false, end2 = false;
            // end 1
            for (int end = 0; end < 2; ++end) {
                string ac = a.fields[end == 0 ? 0 : 5];
                long as = atol(a.fields[end == 0 ? 1 : 6].c_str()) - slop;
                long ae = atol(a.fields[end == 0 ? 2 : 7].c_str()) + slop;
                string bc = b.fields[end == 0 ? 0 : 5];
                long bs = atol(b.fields[end == 0 ? 1 : 6].c_str());
                long be = atol(b.fields[end == 0 ? 2 : 7].c_str());
                if (ac == bc && ae > bs && as < be) {
                    double lenA = (double)(ae - as);
                    long ov = (ae < be ? ae : be) - (as > bs ? as : bs);
                    if (lenA > 0 && (double)ov / lenA >= o.fracA) {
                        if (end == 0) end1 = true; else end2 = true;
                    }
                }
            }
            bool report = false;
            if (type == "both") report = end1 && end2;
            else if (type == "either") report = end1 || end2;
            else if (type == "neither") report = !end1 && !end2;
            else if (type == "notboth") report = !(end1 && end2);
            if (report) outLine(a.raw() + "\t" + b.raw());
        }
    }
    OUT.flush();
    return 0;
}
