    double d = (double)genomeSize - (double)aLen - (double)bLen + (double)inter;
    if (d < 0) d = 0;
    double stat = (a > 0 && d > 0) ? (a*d) / (b > 0 && c > 0 ? (b*c) : 1.0) : 0.0;
    double p = fisherP(a, b, c, d, 0);
    double pl = fisherP(a, b, c, d, 1);
    double pr = fisherP(a, b, c, d, 2);
    auto f6 = [](double v) { std::ostringstream ss; ss << std::setprecision(6) << v; return ss.str(); };
