        else if (arg == "-a") { if (i+1 >= argc) bedFatal("No input file given. Exiting."); aFile = argv[++i]; }
        else if (arg == "-b") { if (i+1 >= argc) bedFatal("-b option given, but no database file specified."); bFile = argv[++i]; }
        else if (arg == "-g") { if (i+1 >= argc) bedFatal("-g option given, but no genome file specified."); gFile = argv[++i]; }
        else if (arg == "-m") mergeFirst = true;
        else if (parseCommonOpt(arg, argc, argv, i, o)) {}
        else { fputs(HELP_fisher, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (aFile.empty() || bFile.empty() || gFile.empty()) {
        fputs(HELP_fisher, stderr); bedFatal("The following parameters are required: -a -b -g");
    }
    if (o.anyWhere && !o.fracASet) { fputs(HELP_fisher, stderr); bedFatal("-e must be used with -f."); }
    if (o.anyWhere && !o.fracBSet) o.fracB = 0.0;
    GENOME.load(gFile);
    vector<FileBins> bsets;
    vector<vector<BedRec> > recsets;
    vector<string> bp(1, bFile);
    loadFiles(bp, bsets, recsets);
    vector<BedRec> arecs;
    vector<string> aheader;
    loadRecords(aFile, arecs, aheader);
    if (o.sorted) {
        checkSorted(arecs, aFile, o);
        checkSorted(recsets[0], bFile, o);
    }
    vector<BedRec> ar = arecs, br = recsets[0];
    if (mergeFirst) {
        vector<BedRec> m;
        for (size_t i = 0; i < ar.size(); ++i) {
            if (!m.empty() && m.back().chrom() == ar[i].chrom() && ar[i].start <= m.back().end) {
                if (ar[i].end > m.back().end) m.back().end = ar[i].end;
            } else m.push_back(ar[i]);
        }
        ar.swap(m);
        m.clear();
        for (size_t i = 0; i < br.size(); ++i) {
            if (!m.empty() && m.back().chrom() == br[i].chrom() && br[i].start <= m.back().end) {
                if (br[i].end > m.back().end) m.back().end = br[i].end;
            } else m.push_back(br[i]);
        }
        br.swap(m);
    }
    long basesA = 0, basesB = 0, inter = 0;
    for (size_t i = 0; i < ar.size(); ++i) basesA += ar[i].len();
    for (size_t i = 0; i < br.size(); ++i) basesB += br[i].len();
    vector<Hit> hits;
    for (size_t ai = 0; ai < ar.size(); ++ai) {
        const BedRec &a = ar[ai];
        collect(bsets, a.chrom(), a.start, a.end, hits);
        for (size_t j = 0; j < hits.size(); ++j) {
            if (!overlapsOK(a, *hits[j].rec, o)) continue;
            long ov = overlapBases(a, *hits[j].rec);
            if (ov > 0) inter += ov;
        }
    }
    long genomeSize = 0;
    for (size_t i = 0; i < GENOME.chroms.size(); ++i) genomeSize += GENOME.size(GENOME.chroms[i]);
    long aLen = basesA, bLen = basesB;
    // contingency: covered by both / only A / only B / neither
    double a = inter;
    double b = aLen - inter;
    double c = bLen - inter;
    double d = (double)genomeSize - (double)aLen - (double)bLen + (double)inter;
    if (d < 0) d = 0;
    double stat = (a > 0 && d > 0) ? (a*d) / (b > 0 && c > 0 ? (b*c) : 1.0) : 0.0;
    double p = fisherP(a, b, c, d, 0);
    double pl = fisherP(a, b, c, d, 1);
    double pr = fisherP(a, b, c, d, 2);
    auto f6 = [](double v) { std::ostringstream ss; ss << std::setprecision(6) << v; return ss.str(); };
    outLine("fisher statistic:  " + f6(stat));
    outLine("fisher p-value:    " + f6(p));
    outLine("fisher left p:     " + f6(pl));
    outLine("fisher right p:    " + f6(pr));
    outLine("fisher two-tail p: " + f6(p));
    OUT.flush();
    return 0;
}

