    map<string, long> chromDepth;
    long genomeSize = 0;
    for (size_t i = 0; i < order.size(); ++i) {
        const string &c = order[i];
        long size = GENOME.ok ? GENOME.size(c) : 0;
        if (size < 0) size = 0;
        genomeSize += size;
        vector<pair<long,int> > evs;
        for (size_t j = 0; j < recs.size(); ++j) {
            if (recs[j].chrom() != c) continue;
            if (!strand.empty()) {
                if (!recs[j].hasStrand() || recs[j].strand() != strand) continue;
            }
            long s = recs[j].start, e = recs[j].end;
            if (s < 0) s = 0;
            if (e > size) e = size;
            if (e > s) { evs.push_back(make_pair(s, 1)); evs.push_back(make_pair(e, -1)); }
        }
        std::sort(evs.begin(), evs.end());
        vector<Run> rv;
        long cur = 0, dep = 0;
        for (size_t j = 0; j < evs.size(); ++j) {
            long pos = evs[j].first;
            if (pos > cur) {
                if (dep != 0 || true) { Run r; r.start = cur; r.end = pos; r.depth = dep; rv.push_back(r); }
                cur = pos;
            }
            dep += evs[j].second;
        }
        if (cur < size) { Run r; r.start = cur; r.end = size; r.depth = dep; rv.push_back(r); }
        runs[c] = rv;
    }
