        else if (arg == "-c") { if (i+1>=argc) bedFatal("Please specify a column for -c"); cols.clear(); splitList(argv[++i], cols); haveCols = true; }
        else if (arg == "-o") { if (i+1>=argc) bedFatal("Please specify an operation for -o"); ops.clear(); splitList(argv[++i], ops); haveOps = true; }
        else if (arg == "-delim") { if (i+1>=argc) bedFatal("Please specify a delimiter for -delim"); delim = argv[++i]; }
        else if (arg == "-prec") { if (i+1>=argc) bedFatal("Please specify a precision for -prec"); prec = atoi(argv[++i]); }
        else if (arg == "-header") header = true;
        else if (arg == "-bed") {}
        else if (arg == "-nobuf") OUT.nobuf = true;
        else if (arg == "-iobuf") { if (i+1<argc) ++i; }
        else { fputs(HELP_merge, stderr); bedFatal("Unrecognized parameter: " + arg); }
    }
    if (inFile.empty()) { fflush(stdout); return 0; }
    vector<int> colNums; vector<string> colOps;
    if (haveCols || haveOps) {
        if (cols.empty()) cols.push_back("5");
        if (ops.empty()) ops.push_back("sum");
        if (cols.size() == 1 && ops.size() > 1) {
            for (size_t i = 0; i < ops.size(); ++i) { colNums.push_back(atoi(cols[0].c_str())); colOps.push_back(ops[i]); }
        } else if (ops.size() == 1 && cols.size() > 1) {
            for (size_t i = 0; i < cols.size(); ++i) { colNums.push_back(atoi(cols[i].c_str())); colOps.push_back(ops[0]); }
        } else if (cols.size() == ops.size()) {
            for (size_t i = 0; i < cols.size(); ++i) { colNums.push_back(atoi(cols[i].c_str())); colOps.push_back(ops[i]); }
        } else bedFatal("Please provide the same number of columns and operations.");
