        string out = cur.chrom() + "\\t" + num2str(cur.start) + "\\t" + num2str(cur.end);
        for (size_t c = 0; c < colNums.size(); ++c) {
            int col = colNums[c];
            vector<string> v;
            for (size_t j = 0; j < vals.size(); ++j)
                v.push_back(((size_t)(col-1) < vals[j].fields.size()) ? vals[j].fields[col-1] : string("."));
            out += "\\t" + applyNumOp(colOps[c], v, delim, prec, col);
        }
        fprintf(stdout, "%s\\n", out.c_str());
    };
    BedRec cur;
    vector<BedRec> runVals;
    bool have = false;
