                if (!r.hasStrand() || !cur.hasStrand() || r.strand() != cur.strand()) canMerge = false;
            }
            if (canMerge && !forceStrand.empty()) {
                if (!r.hasStrand() || r.strand() != forceStrand) canMerge = false;
            }
        }
        if (canMerge) {
            if (r.end > cur.end) cur.end = r.end;
            runVals.push_back(r);
        } else {
            if (have) emitRun(cur, vector<int>(), runVals);
            cur = r;
            runVals.clear(); runVals.push_back(r);
            have = true;
        }
    }
    if (have) emitRun(cur, vector<int>(), runVals);
    fflush(stdout);
    return 0;
}

