j=s.index('int cmd_fisher(')
new='''// Fisher's exact test for a 2x2 table
static double fisherP(double a, double b, double c, double d, int tail) {
    // tail: 0 = two-tail, 1 = left, 2 = right
    double n = a + b + c + d;
    if (n <= 0) return 1.0;
    double r1 = a + b, c1 = a + c;
    if (r1 <= 0 || c1 <= 0 || n - r1 <= 0 || n - c1 <= 0) return 1.0;
    double lobs = lgamma(r1+1) + lgamma(n-r1+1) + lgamma(c1+1) + lgamma(n-c1+1)
                  - lgamma(n+1) - lgamma(a+1) - lgamma(b+1) - lgamma(c+1) - lgamma(d+1);
    double pobs = exp(lobs);
    double lo = c1 - (n - r1) > 0 ? c1 - (n - r1) : 0;
    double hi = c1 < r1 ? c1 : r1;
    double sum = 0;
    for (double x = lo; x <= hi; x += 1) {
        double dd = c1 - x;
        if (dd < 0 || (r1 - x) < 0 || (n - r1 - dd) < 0) continue;
        double l = lgamma(r1+1) + lgamma(n-r1+1) + lgamma(c1+1) + lgamma(n-c1+1)
                   - lgamma(n+1) - lgamma(x+1) - lgamma(r1-x+1) - lgamma(dd+1) - lgamma(n-r1-dd+1);
        double p = exp(l);
        if (tail == 0) {
            if (p <= pobs * (1 + 1e-7)) sum += p;
        } else if (tail == 1) {
            if (x <= a) sum += p;
        } else {
            if (x >= a) sum += p;
        }
    }
    if (sum > 1.0) sum = 1.0;
    return sum;
}

'''
