{"command": "cd /tmp/rt && cat > bf.py <<'PY'
import random, subprocess, sys
B="/workspace/bt"
def gen(n, chroms=("chr1","chr2"), maxpos=1000, maxfields=6, strand=True):
    lines=[]
    for i in range(n):
        c=random.choice(chroms)
        s=random.randint(0,maxpos-20)
        e=s+random.randint(0,50)
        f=[c,str(s),str(e)]
        if maxfields>=4: f.append("n%d"%i)
        if maxfields>=5: f.append(str(random.randint(0,100)))
        if maxfields>=6 and strand: f.append(random.choice("+-"))
        lines.append("\t".join(f))
    return "\n".join(lines)+"\n"
def overlapsOK(a,b,o):
    ov=min(a[2],b[2])-max(a[1],b[1])
    la=a[2]-a[1]; lb=b[2]-b[1]
    ovA=ov/la if la>0 else 0.0
    ovB=ov/lb if lb>0 else 0.0
    if o.get('e'):
        ok = ovA>=o.get('f',1e-9) or ovB>=o.get('F',0.0)
    elif o.get('r'):
        ok = ovA>=o.get('f',1e-9) and ovB>=o.get('f',1e-9)
    else:
        ok = ovA>=o.get('f',1e-9) and ovB>=o.get('F',1e-9)
    if not ok: return False
    if o.get('s') or o.get('S'):
        if len(a)<6 or len(b)<6: return False
        sa=a[5]; sb=b[5]
        if o.get('s') and sa!=sb: return False
        if o.get('S') and sa==sb: return False
    return True
def run_case(seed):
    random.seed(seed)
    na=random.randint(1,8); nb=random.randint(1,10)
    fa=random.randint(3,6); fb=random.randint(3,6)
    A=gen(na,maxfields=fa); Bf=gen(nb,maxfields=fb)
    open('/tmp/rt/x_a.bed','w').write(A)
    open('/tmp/rt/x_b.bed','w').write(Bf)
    opts=sys.argv[1:] if len(sys.argv)>1 else []
    cmd=[B,"intersect","-a","/tmp/rt/x_a.bed","-b","/tmp/rt/x_b.bed"]+opts
    p=subprocess.run(cmd,capture_output=True,text=True)
    got=p.stdout.rstrip("\n").split("\n") if p.stdout.strip() else []
    # brute force
    A=[l.split("\t") for l in A.rstrip("\n").split("\n")]
    Bl=[l.split("\t") for l in Bf.rstrip("\n").split("\n")]
    exp=[]
    o={}
    for opt in opts:
        if opt in ("-s",): o['s']=1
        elif opt in ("-S",): o['S']=1
        elif opt in ("-r",): o['r']=1
        elif opt in ("-e",): o['e']=1
        elif opt=="-f": o['f']=float(opts[opts.index(opt)+1])
        elif opt=="-F": o['F']=float(opts[opts.index(opt)+1])
    mode = "wa_wb" if ("-wa" in opts and "-wb" in opts) else ("wa" if "-wa" in opts else ("c" if "-c" in opts else ("v" if "-v" in opts else ("u" if "-u" in opts else "default"))))
    for a in A:
        hits=[b for b in Bl if overlapsOK(a,b,o)]
        if mode=="default":
            for b in hits:
                s=max(a[1],b[1]); e=min(a[2],b[2])
                exp.append("\t".join([a[0],str(s),str(e)]+a[3:]))
        elif mode=="wa_wb":
            for b in hits: exp.append("\t".join(a)+"\t"+"\t".join(b))
        elif mode=="wa":
            for b in hits: exp.append("\t".join(a))
        elif mode=="c":
            exp.append("\t".join(a)+"\t"+str(len(hits)))
        elif mode=="v":
            if not hits: exp.append("\t".join(a))
        elif mode=="u":
            if hits: exp.append("\t".join(a))
    exp="\n".join(exp)
    got="\n".join(got)
    if exp!=got:
        print("MISMATCH seed",seed,opts)
        print("A:\n"+A)
        print("B:\n"+Bf)
        print("exp:\n"+exp)
        print("got:\n"+got)
        return False
    return True
fails=0
for seed in range(int(sys.argv[2]) if len(sys.argv)>2 else 200):
    if not run_case(seed): fails+=1
    if fails>2: break
print("fails:",fails)
