// read raw tab-delimited lines without any BED validation (used by groupby/expand/overlap)
void loadLines(const string &path, vector<vector<string> > &out) {
    out.clear();
    LineReader lr(path);
    if (!lr.ok()) die("Unable to open file " + path + ". Exiting.");
    string line;
    while (lr.next(line)) {
        if (line.empty()) continue;
        vector<string> f;
        splitStr(line, '\t', f);
        out.push_back(f);
    }
}
